/* Authored v8 lessons. Existing lesson IDs and saved progress remain intact. */
const CASE_TASKS8={};
const NEW_LESSON_IDS8=[];
const CURRICULUM_PLAN8='48 authored lessons plus 48 scheduled practice/review/project weeks; not 96 fully authored lesson chapters.';
const REFS8={
 windows:{title:['Microsoft：文件资源管理器','Microsoft: File Explorer'],url:'https://support.microsoft.com/en-us/windows/experience/fileexplorer/file-explorer-in-windows'},
 cmd:{title:['Microsoft：CMD的cd命令','Microsoft: CMD cd command'],url:'https://learn.microsoft.com/en-us/windows-server/administration/windows-commands/cd'},
 linux:{title:['Ubuntu：终端入门','Ubuntu: command-line introduction'],url:'https://ubuntu.com/tutorials/command-line-for-beginners'},
 wsl:{title:['Microsoft：安装WSL（独立环境准备）','Microsoft: install WSL (separate environment setup)'],url:'https://learn.microsoft.com/en-us/windows/wsl/install'},
 gccsetup:{title:['Ubuntu：准备GCC开发环境','Ubuntu: prepare a GCC development environment'],url:'https://ubuntu.com/developers/docs/howto/gcc-setup/'},
 c:{title:['GNU：C语言入门与参考','GNU: C introduction and reference'],url:'https://www.gnu.org/software/c-intro-and-ref/manual/c-intro-and-ref.html'},
 gcc:{title:['GCC：编译输出与阶段','GCC: output and compilation stages'],url:'https://gcc.gnu.org/onlinedocs/gcc/Overall-Options.html'},
 board:{title:['SparkFun：面包板的内部连接','SparkFun: breadboard connections'],url:'https://learn.sparkfun.com/tutorials/how-to-use-a-breadboard/all'},
 solder:{title:['Adafruit：焊接基础','Adafruit: soldering fundamentals'],url:'https://learn.adafruit.com/adafruit-guide-excellent-soldering'},
 px4:{title:['PX4：装配与配置（匹配实际版本）','PX4: assembly and configuration (match your version)'],url:'https://docs.px4.io/main/en/assembly/quick_start_pixhawk4'},
 safety:{title:['PX4：失控保护与仿真检查','PX4: failsafe configuration and simulation checks'],url:'https://docs.px4.io/main/en/config/safety'},
 ros:{title:['ROS 2 Jazzy：官方教程','ROS 2 Jazzy: official tutorials'],url:'https://docs.ros.org/en/jazzy/Tutorials.html'},
 urdf:{title:['ROS robot_state_publisher','ROS robot_state_publisher'],url:'https://github.com/ros/robot_state_publisher'}
};
function addLesson8(d){
 if(LESSONS.some(l=>l.id===d.id))throw new Error('Duplicate curriculum lesson: '+d.id);
 const [scenario,predict,operate,explain,transfer,evidence,pass]=d.task;
 const labNote=d.labNote||['本节需要在指定文件夹、纸面或外部工具完成作业；网页不执行这些命令，也不会自动证明实物已通过检查。','Complete this exercise in the specified folder, on paper or in the external tool. This page does not execute commands or certify hardware checks.'];
 const l={id:d.id,area:d.area,level:d.level||'Foundation',title:d.title[0],tags:d.title.join(' ')+' v8',time:'60–90 min + practice',desc:d.goal[0],prereq:d.pre||[],lab:d.lab||'cpu',goals:[d.goal[0]],sections:d.sections.map(s=>[s[0],s[2]]),example:d.example[0],task:operate[0],quiz:[predict[0],d.answer[0]],v8:true};
 LESSONS.push(l);NEW_LESSON_IDS8.push(d.id);DEEP_LESSONS[d.id]=d.sections;
 EN_LESSONS[d.id]={title:d.title[1],idea:d.goal[1],example:d.example[1],error:d.error[1]};
 WORKED_EXAMPLES7[d.id]=d.example;
 LESSON_GUIDE7[d.id]={goal:d.goal,practice:operate,question:predict,answer:d.answer,labNote,labMode:'concept',misconception:d.error};
 LESSON_REFERENCES7[d.id]=(d.refs||[]).map(k=>REFS8[k]);
 CASE_TASKS8[d.id]={scenario,predict,steps:[operate,explain,transfer],evidence:[evidence],rubric:[pass],reviewDays:[1,7,30],explain,transfer};
}

addLesson8({id:'pc-parts',area:'电脑零基础',title:['先认识电脑：设备、系统、程序和文件','Computer, operating system, application and file'],goal:['能把一次保存操作对应到程序、内存和存储，并找到自己保存的文件。','Relate saving to an application, memory and storage and locate the saved file.'],refs:['windows'],sections:[
 ['四层分别负责什么','Four different roles','键盘把输入送给电脑，操作系统管理设备和文件，程序完成编辑任务，文件保存结果。网页、浏览器和Windows不是同一个东西：网页在浏览器中显示，浏览器是Windows运行的程序。','The keyboard supplies input, the OS manages devices/files, applications perform tasks and files store results. A webpage is displayed by a browser, which is an application running under the operating system.'],
 ['内存不是保存位置','Memory is not a save location','程序正在编辑的内容通常先在内存中；保存会把内容写入选定存储位置。关闭窗口、关闭电脑和保存是不同动作。自动恢复可能帮助找回内容，但不能代替确认文件已保存。','Editing normally changes data in memory; saving writes it to a selected storage location. Closing a window, shutting down and saving are distinct actions. Recovery features do not replace checking the saved file.'],
 ['用窗口完成一个闭环','Complete a window workflow','打开记事本，输入三行学习目标，选择另存为，记录文件名和文件夹。关闭后从文件夹重新打开；如果内容一致，才证明这一次保存与定位都完成，而不只是屏幕上曾经显示过。','Open a text editor, enter three learning goals, choose Save As and record name and folder. Close and reopen from that folder. Matching contents demonstrate both saving and locating, rather than merely displaying text.'],
 ['读清对话框再确认','Read a dialog before confirming','覆盖提示询问的是是否替换同名文件；关闭前的保存提示询问是否保留未写入磁盘的修改。取消通常能退出本次操作。先在练习副本上辨认按钮，不用真实重要文件试错。','Overwrite asks whether to replace an existing same-named file; a save-on-close prompt concerns unsaved edits. Cancel usually abandons that operation. Learn these choices using practice copies, not important originals.']
 ],example:['在study.txt中写“本周学习文件管理”，保存后关闭，再打开看到同一句话。把新句子写入但选择不保存关闭，重新打开仍应是旧内容。','Save “This week: file management” in study.txt and reopen it. Add a sentence but close without saving; reopening should show the previously saved content.'],error:['最小化不等于保存；桌面图标也不一定是文件本体。','Minimizing is not saving, and a desktop icon may be a shortcut rather than the file itself.'],answer:['没有保存的新修改可能随关闭丢失；用重新打开的文件内容验证，不能只凭窗口曾经显示过判断。','Unsaved changes can be lost on close. Verify by reopening the file rather than remembering what the window showed.'],task:[['为自己建立第一份学习记录。','Create your first learning record.'],['不保存新句子就关闭，重新打开会看到什么？','What remains after closing an added sentence without saving?'],['在练习文件中完成输入、保存、关闭、重新打开，再试一次不保存。','Enter, save, close and reopen a practice file, then repeat without saving an edit.'],['用一句话分别解释内存里的编辑与磁盘上的文件。','Explain edited memory and the saved file separately.'],['换一个新文件名，在另一个练习文件夹重做。','Repeat under a new filename in another practice folder.'],['保留两个文件及记录的完整位置。','Keep the two files and their recorded locations.'],['不依赖最近文件列表，能从文件夹找到并重开正确版本。','Locate and reopen the correct version without relying on Recent files.']]});

addLesson8({id:'win-files',area:'电脑零基础',title:['文件、文件夹、扩展名与快捷方式','Files, folders, extensions and shortcuts'],pre:['pc-parts'],goal:['能显示扩展名、区分文件类型与快捷方式，并整理学习材料。','Show extensions, distinguish file types/shortcuts and organize study materials.'],refs:['windows'],sections:[
 ['目录是容器，文件是内容','Folders contain files','创建Academy练习文件夹，再建notes、code、exports三个子文件夹。文件夹可以装文件和其他文件夹；同一文件夹不能有完全相同的文件名，但不同文件夹可以各有readme.txt。','Create an Academy practice folder with notes, code and exports subfolders. Folders contain files and other folders. The same complete filename cannot occur twice in one folder but can occur in different folders.'],
 ['把扩展名显示出来','Make extensions visible','在资源管理器的查看选项里启用文件扩展名，辨认.txt、.c、.html、.zip和.exe。扩展名帮助系统选择打开方式，不会把内容转换为另一种格式；把照片改名.c不会得到C程序。','Enable filename extensions in File Explorer. Identify .txt, .c, .html, .zip and .exe. An extension helps choose an opener; renaming an image to .c does not convert it into C source.'],
 ['复制和移动的区别','Copy versus move','复制后原位置通常仍有文件；移动后文件改到新位置。先复制一份练习文本，分别编辑副本与原件，观察它们不是自动同步的两个窗口。涉及同名替换时先比较内容和修改时间。','Copy normally retains the source; move changes location. Edit a practice copy and the original separately to see they are independent. Before replacing a same-named file, compare content and modification time.'],
 ['快捷方式指向目标','A shortcut points elsewhere','快捷方式通常记录目标位置及启动参数。删除快捷方式一般不删除目标，移动目标却可能令快捷方式失效。分享材料时应分享目标文件或完整安装包，不能只把自己的快捷方式发给别人。','A shortcut records a target and often launch arguments. Removing it generally leaves the target; moving the target may break the shortcut. Share the real files or installer, not merely your own shortcut.']
 ],example:['notes中report.txt复制到exports后，两处各有一个文件；只修改exports副本，notes内容不变。report.txt.exe的最后扩展名是.exe，不是.txt。','Copy report.txt from notes to exports: there are now two files. Editing exports leaves notes unchanged. The final extension of report.txt.exe is .exe, not .txt.'],error:['扩展名、图标和文件内容相关但不是同一件事；不要靠图标判定来源可信。','Extension, icon and content are related but distinct; an icon does not establish trust.'],answer:['复制生成独立副本，之后修改一份不会自动改另一份，除非另有同步系统参与。','A copy is independent; later edits do not update the other copy unless a separate synchronization mechanism intervenes.'],task:[['收到一组课程源码、说明与压缩包，需要整理。','Organize a set of course source, notes and archives.'],['修改复制后的文本，原件会一起变吗？','Will editing the copied text change its original?'],['建立三个子目录，显示扩展名，复制并编辑练习文本。','Create three subfolders, show extensions and edit a copied practice text.'],['说明.c、.exe、.zip和快捷方式各表示什么。','Explain .c, .exe, .zip and a shortcut.'],['让同伴只靠你的目录说明找到指定文件。','Have another person locate a file using only your folder description.'],['保存目录截图与文件清单，不含个人路径。','Keep a folder view and file list without personal paths.'],['能指出文件真正位置、扩展名以及哪份是副本。','Identify actual location, extension and which file is the copy.']]});

addLesson8({id:'win-paths',area:'电脑零基础',title:['路径、盘符与当前目录','Paths, drives and the current directory'],pre:['win-files'],goal:['能从路径找到文件，区分绝对和相对路径，处理空格。','Locate files from paths and distinguish absolute/relative paths and spaces.'],refs:['windows','cmd'],sections:[
 ['路径像逐层地址','A path is a layered address','Windows路径可写为C:\\Academy\\notes\\day1.txt。C:是盘符，反斜杠分隔层级，最后一段是文件名。本课路径只是示例；实际练习放在自己有写入权限的文件夹，不强求创建C盘根目录。','A path such as C:\\Academy\\notes\\day1.txt contains a drive, backslash-separated folders and a filename. It is an example, not a requirement to write at the drive root; use a writable practice folder.'],
 ['相对路径依赖起点','Relative paths depend on a starting point','位于Academy时，notes\\day1.txt指向其notes子目录；位于code时，同样文字会找code下面的notes。..表示上一级，因此从code访问同级notes可用..\\notes\\day1.txt。','From Academy, notes\\day1.txt refers to its notes child. From code, the same text looks under code. The .. segment means parent, so ..\\notes\\day1.txt reaches the sibling notes directory.'],
 ['空格要保留为一个参数','Keep a spaced path together','路径My Course含空格，命令行通常需要用成对双引号包住完整路径。引号是命令解释的边界，不是文件名的一部分。复制路径时还要辨认复制到的是网页地址还是本地文件路径。','A path containing My Course usually needs double quotes to stay one command argument. The quotes delimit the argument, not the filename. Distinguish a web URL from a local filesystem path.'],
 ['用地址栏核对，不凭感觉','Verify the address','在资源管理器地址栏查看完整位置，进入子目录再返回上一级，观察地址变化。遇到“找不到文件”先检查盘符、当前目录、拼写与扩展名；不要立刻重新安装软件。','Inspect the full address in File Explorer, enter a child and return to the parent. When a file is missing, check drive, current directory, spelling and extension before assuming the application needs reinstalling.']
 ],example:['当前目录为Academy\\code，文件在Academy\\notes\\day1.txt，相对路径为..\\notes\\day1.txt。换到Academy后，应使用notes\\day1.txt。','From Academy\\code, use ..\\notes\\day1.txt to reach Academy\\notes\\day1.txt. From Academy itself, use notes\\day1.txt.'],error:['相同相对路径在不同当前目录下可能指向不同地方。','The same relative path can name different locations from different current directories.'],answer:['从code先回到父目录Academy，再进入notes，因此需..\\notes\\day1.txt。','Go from code to parent Academy, then notes: ..\\notes\\day1.txt.'],task:[['把说明文件交给只知道起点文件夹的人。','Give instructions to someone who knows only the starting folder.'],['从code怎样找到同级notes里的day1.txt？','How do you reach notes/day1.txt from sibling code?'],['画三层目录树，分别从父目录与子目录写出目标相对路径并打开。','Draw a three-level tree and open a target using paths from parent and child folders.'],['解释为什么两个正确路径写法不同。','Explain why the two correct path strings differ.'],['把Academy整体复制到另一位置，再检验哪些相对路径仍成立。','Copy the whole Academy folder elsewhere and test which relative paths still work.'],['提交目录树和三组起点→路径→目标记录。','Submit the tree and three start→path→target records.'],['三次定位正确，能说明..和引号的作用。','Locate all three targets and explain .. and quotes.']]});

addLesson8({id:'win-zip',area:'电脑零基础',title:['压缩、解压与可复现分享','Archives, extraction and reproducible sharing'],pre:['win-paths'],goal:['能制作不漏依赖的ZIP并在新目录复查。','Create a ZIP with its dependencies and verify a clean extraction.'],refs:['windows'],sections:[
 ['压缩包不是已安装程序','An archive is not an installation','ZIP把一组文件与相对目录收在一个文件中。浏览器下载成功只说明压缩包到了电脑；必须完整解压到普通目录再按说明启动，不能把“在压缩包里预览”当作正常运行环境。','A ZIP stores files and their relative hierarchy in one archive. Downloading it does not install the application. Extract fully to a normal folder before following launch instructions; archive preview is not a normal runtime directory.'],
 ['保留相对目录关系','Preserve the hierarchy','如果HTML引用images中的图片，只复制HTML可能丢图。把共同父目录作为打包边界，包含必要资源与README。排除个人笔记、缓存、密钥和无关大文件，清单中说明哪个文件是入口。','If HTML references images, copying only HTML can lose them. Package the common parent with needed resources and README. Exclude personal notes, caches, secrets and unrelated files and identify the entry point.'],
 ['在空目录做接收者测试','Test as a recipient','将ZIP解压到一个新的空练习目录，断开对原目录的依赖，再按README打开入口。检查图片、链接和本地数据是否正常；自己的桌面快捷方式不是新电脑的启动入口。','Extract into a fresh practice folder and launch only from that copy following the README. Check assets, links and local data. Your existing desktop shortcut is not the recipient’s entry point.'],
 ['备份需要恢复试验','A backup needs a restore test','备份不仅是文件存在，还包括能读取和恢复。记录包版本、文件数、解压后入口与检查日期；程序产生的学习进度应另按导出功能备份，不能假定打包程序目录会带走浏览器数据。','A backup must be readable and restorable. Record version, file count, entry point and check date. Export learning progress separately; archiving application files does not necessarily include browser storage.']
 ],example:['建立demo/index.html与demo/images/a.svg，压缩demo后在fresh目录解压。若HTML中的相对引用保持images/a.svg，目录结构保持时仍能找到图片。','Create demo/index.html and demo/images/a.svg. Archive demo and extract in fresh. The relative images/a.svg reference still resolves when the hierarchy is preserved.'],error:['重命名.zip为.exe不会生成安装程序，压缩也不会自动安装运行环境。','Renaming .zip to .exe does not create an installer or install dependencies.'],answer:['应包含共同父目录中的HTML、images与必要说明，保留它们的相对关系。','Include HTML, images and instructions under their common parent and preserve relative relationships.'],task:[['把一个含资源的小项目交给另一台电脑。','Share a small project with its resources.'],['只发入口文件，哪些引用可能失效？','Which references may fail if only the entry file is sent?'],['整理项目、创建ZIP、在新空目录完整解压并启动入口。','Organize, ZIP, extract in a fresh folder and launch the entry.'],['写出一次缺失资源的原因及修复。','Explain one missing-resource failure and its repair.'],['请接收者按README操作，记录他停在哪一步。','Have a recipient follow the README and record any sticking point.'],['提交ZIP、文件清单与接收者测试记录。','Submit archive, inventory and recipient test record.'],['新目录运行通过，包内无个人资料，入口只需一句说明。','The fresh copy works, contains no personal material and has a one-sentence launch instruction.']]});

addLesson8({id:'win-tools',area:'电脑零基础',title:['安装器、便携程序、版本与环境变量','Installers, portable tools, versions and PATH'],pre:['win-zip'],goal:['能区分安装和运行，解释PATH查找并记录工具版本。','Distinguish installation/execution, explain PATH and record tool versions.'],refs:['windows','cmd'],sections:[
 ['先知道下载的是什么','Identify the download','安装器复制文件并可能创建快捷方式、卸载信息；便携程序常在解压目录直接运行；源码还需要构建。下载前核对发布者、系统架构和版本，不把“源码ZIP”当作已经编好的Windows程序。','An installer may copy files and register shortcuts/uninstall information. Portable software often runs from its extracted folder. Source needs building. Check publisher, architecture and version; a source ZIP is not a ready Windows binary.'],
 ['PATH只是查找目录列表','PATH is a search list','输入程序名时，终端按命令规则和PATH目录查找可执行文件。PATH不会下载软件，也不会改变程序语言。重复安装不同版本可能让先找到的版本并非预期，应同时记录可执行文件位置与版本。','A terminal resolves commands using shell rules and PATH directories. PATH neither downloads tools nor changes their language. Multiple versions can cause an unexpected executable to be found first; record location and version.'],
 ['新终端才可能看到新设置','Processes inherit environments','环境变量通常在进程启动时继承。安装器改变PATH后，旧终端可能仍用旧值，先关闭并重新打开再检查。不要为“找不到命令”随意覆盖整条PATH，应先确认程序文件确实存在。','Processes usually inherit environment variables at startup. After an installer updates PATH, an old terminal may retain its old value. Reopen and verify; do not replace the entire PATH just because a command is missing.'],
 ['把环境记录变成复现资料','Record a reproducible environment','记录操作系统、工具版本、安装来源和最小运行结果。截图只能证明某个画面，还应抄下完整错误文本。没有管理员权限时优先遵循工具的用户级安装说明，不默认提升权限解决所有问题。','Record OS, tool version, source and a minimal run. Preserve complete error text as well as screenshots. Without administrator access, follow supported per-user installation guidance rather than elevating every operation.']
 ],example:['工具文件已存在，旧CMD提示找不到命令，新CMD能显示版本。这可能是环境继承差异；用where 工具名检查实际路径，而不是立刻再装一次。','A tool exists but only a newly opened CMD finds it. Inherited environment differences may explain this. Use where with the tool name to inspect the resolved path before reinstalling.'],error:['“安装完成”不等于“最小程序已验证”，同名命令也可能来自不同版本。','Installation success is not a verified minimal run, and the same command name may resolve to different versions.'],answer:['PATH只负责查找已存在的程序；还要核对程序文件、当前终端环境和实际解析路径。','PATH only helps locate an existing program; check the file, terminal environment and resolved executable.'],task:[['建立以后编程工具的环境记录卡。','Create an environment record for future programming tools.'],['PATH里有目录，是否保证目录里存在程序？','Does a directory in PATH guarantee the program exists there?'],['记录系统与一个已安装工具的版本，在新终端核对其位置。','Record OS and one installed tool’s version and resolve its location in a fresh terminal.'],['区分安装失败、命令查找失败与程序运行失败。','Distinguish installation, lookup and execution failures.'],['把记录交给同伴，让他指出还缺哪项复现信息。','Ask a peer to identify missing reproduction information.'],['提交来源、版本、路径类型与最小运行记录；公开版本去掉用户名。','Submit source, version, path category and minimal run; remove usernames from public copies.'],['能说明所运行的确切版本，不依靠猜测或重复安装。','Identify the exact executed version without guessing or repeated installation.']]});

addLesson8({id:'win-cmd',area:'电脑零基础',title:['CMD第一组命令：查看、进入、建练习目录','First CMD commands: inspect, navigate and create a practice folder'],pre:['win-paths','win-tools'],goal:['能读懂提示符、在已确认练习目录执行只读命令，并定位命令错误。','Read the prompt, inspect a known practice directory and diagnose command errors.'],refs:['cmd'],sections:[
 ['终端、Shell与提示符','Terminal, shell and prompt','终端是交互窗口，CMD和PowerShell是不同命令解释器。本课使用CMD；提示符中的路径帮助确认当前目录。教程显示的C:\\...>是提示信息，不应整段复制成命令输入。','The terminal is an interface; CMD and PowerShell are different shells. This lesson uses CMD. The prompt path helps locate the current directory. Do not copy an illustrative C:\\...> prompt as part of a command.'],
 ['先用只读命令看清位置','Inspect before changing','输入cd查看当前目录，dir列出其中内容，type readme.txt显示练习文本。命令、选项和文件参数用空格分隔。读到错误后先看错误属于路径不存在、文件不存在还是命令找不到。','Use cd to show location, dir to list contents and type readme.txt to display practice text. Spaces separate commands/options/arguments. Distinguish missing directory, missing file and unknown-command errors.'],
 ['切目录和切盘符','Change folder and drive','CMD中跨盘切换使用cd /d并给出已确认完整路径。cd ..返回父目录。进入自己创建的练习目录后，可用mkdir session01建立子目录，再dir确认；不要在系统目录做练习。','In CMD, cd /d changes drive and directory together when given a verified path. cd .. moves to the parent. Inside your own practice folder, mkdir session01 creates a child; confirm using dir. Avoid system directories.'],
 ['输出重定向会修改文件','Redirection can overwrite','>把输出写入文件，已存在的同名文件可能被截断；>>追加。初学时先在屏幕读结果，确认目录后才对可丢弃副本练习。遇到del、rmdir、format等陌生命令先读帮助，不作为本课作业。','The > operator writes output and may truncate an existing file; >> appends. Inspect on screen first and use disposable copies for practice. Read help for unfamiliar deletion/format commands; they are not exercises here.']
 ],example:['在练习目录运行mkdir session01，再dir应出现该目录。进入后cd显示路径多了session01；执行cd ..后回到原位置。所有命令一行一条执行。','In the practice folder, mkdir session01 creates a child shown by dir. Enter it and cd shows the additional segment; cd .. returns. Run each command separately.'],error:['CMD和PowerShell的同名词可能语义不同；不要把多行网页代码盲目粘贴执行。','Same-looking CMD/PowerShell commands may differ. Do not blindly paste a block of commands from a webpage.'],answer:['cd显示位置，dir显示目录内容，type显示文本；它们不互相替代。','cd shows location, dir lists contents and type displays text; they serve different roles.'],task:[['用终端找到并查看自己的学习说明。','Locate and read your learning note in a terminal.'],['cd、dir、type分别应显示什么？','What should cd, dir and type display?'],['逐条运行查看目录、列文件、读文本、创建session01并返回父目录。','Individually inspect location, list files, read text, create session01 and return to parent.'],['记录一个拼错文件名的错误并解释它。','Record and explain one misspelled-filename error.'],['在名称含空格的练习副本上重新完成定位。','Repeat navigation in a practice copy whose folder name has spaces.'],['提交命令及预期/实际输出，不含真实个人路径。','Submit commands and expected/actual output without personal paths.'],['每条命令都能先说明作用和目标目录，且未操作练习范围之外。','Explain each command and target directory before running; stay inside practice scope.']]});

addLesson8({id:'linux-start',area:'Linux基础',title:['Linux、Ubuntu和WSL：先确定你在哪个系统','Linux, Ubuntu and WSL: identify your environment'],pre:['win-cmd'],goal:['能区分Windows与Linux环境，记录发行版并进入自己的Linux家目录。','Distinguish Windows/Linux environments, record the distribution and find the Linux home directory.'],refs:['linux','wsl'],sections:[
 ['Linux不是一个窗口主题','Linux is more than a theme','Linux内核、发行版和桌面环境不同。Ubuntu是一种发行版；终端可以运行在原生Linux、虚拟机或WSL中。三者的设备访问、网络和图形支持不同，成功运行终端不等于相机或机器人USB已可用。','A Linux kernel, distribution and desktop are distinct. Ubuntu is a distribution; it can run natively, in a VM or under WSL. Device, network and graphics behavior differs, so a working terminal does not establish hardware access.'],
 ['先读环境身份','Read environment identity','在Linux终端用cat /etc/os-release查看发行版，用uname -m查看架构，用pwd查看目录。记录实际输出，不抄教程截图的版本。后续ROS与软件包都要匹配这个环境。','In a Linux shell, cat /etc/os-release shows distribution details, uname -m shows architecture and pwd shows location. Record actual values rather than a tutorial screenshot; packages and ROS must match them.'],
 ['家目录与管理员不是一回事','Home directory is not administrator access','~表示当前用户家目录，通常适合放练习工程。/是整个文件系统根目录，root又是管理员用户，两者名字相关却不是同一概念。先在~/academy内操作，不在/etc或/usr手工放作业。','The ~ path means your home directory, suitable for exercises. / is the filesystem root; root is also an administrator account, a different concept. Work under ~/academy rather than putting exercises in /etc or /usr.'],
 ['安装是单独的环境任务','Setup is a separate task','尚未准备Linux时，先选择一种受支持的安装方式并按官方文档完成。安装前确认备份和磁盘空间；不要求新手自行重分区。课程页面的Linux说明不会自动创建WSL或安装Ubuntu。','If Linux is absent, choose a supported setup route and follow its official documentation. Confirm backup and space first; beginners need not repartition disks. This page does not create WSL or install Ubuntu.']
 ],example:['终端提示符看起来像user@host:~$时，$只是提示符，不输入。pwd返回家目录，cat /etc/os-release返回Ubuntu信息，才有当前环境身份的证据。','In a prompt such as user@host:~$, the $ is not typed. pwd and cat /etc/os-release provide evidence of location and distribution.'],error:['CMD中的C盘路径不能原样当成Linux路径；WSL发行版也不等于Windows本身。','A Windows drive path is not directly a Linux path; a WSL distribution is distinct from Windows.'],answer:['必须确认实际Shell和发行版；终端窗口外观不能证明自己正在运行哪套系统。','Inspect the shell/distribution; terminal appearance alone does not identify the environment.'],task:[['为ROS学习建立环境身份卡。','Create an environment identity card for ROS study.'],['同一个终端应用能否打开不同Shell？','Can one terminal application host different shells?'],['在Linux读取发行版、架构和当前目录；尚无Linux则完成官方安装方案与备份清单。','Read distribution, architecture and location; if Linux is absent, prepare an official setup plan and backup list.'],['说明原生、虚拟机与WSL各自意味着什么。','Explain native installation, VM and WSL.'],['在第二个终端重复环境核对。','Repeat identification in a second terminal.'],['提交环境卡；计划状态和实际安装状态分开记录。','Submit the card, separating planned from actually installed state.'],['能明确系统、版本、架构和目录，未把计划当安装成功。','Identify system/version/architecture/location without claiming an unperformed installation.']]});

addLesson8({id:'linux-files',area:'Linux基础',title:['Linux路径、大小写和目录操作','Linux paths, case and directory operations'],pre:['linux-start'],goal:['能在自己的家目录安全创建、复制和定位练习文件。','Create, copy and locate practice files in your home directory.'],refs:['linux'],sections:[
 ['路径分隔与大小写','Separators and case','Linux通常使用/分隔目录，并区分A.txt和a.txt。绝对路径从/起，相对路径从当前目录起。文件名含空格时要引用；~在Shell中有家目录展开规则，不能任意放进字符串中期待相同结果。','Linux uses / and commonly treats A.txt and a.txt as different names. Absolute paths begin at /; relative paths start from the working directory. Quote spaces and remember that shell tilde expansion follows specific rules.'],
 ['看见内容和隐藏文件','Inspect visible and hidden entries','pwd确认位置，ls列内容，ls -la还能看到以点开头的隐藏项和权限信息。.表示当前目录，..表示父目录。隐藏文件不是自动加密，也不说明它一定可以删除。','pwd shows location, ls lists contents and ls -la includes dot-prefixed entries and permissions. . is current directory and .. is parent. Hidden files are neither automatically encrypted nor automatically disposable.'],
 ['只在练习目录变更','Change only practice data','先cd进入家目录，再mkdir -p academy/linux01建立练习区。cp复制、mv移动或重命名，都要明确来源和目标；目标同名文件可能被覆盖。第一次先看帮助并用可丢弃文本验证。','Create academy/linux01 under your home using mkdir -p. cp copies; mv moves or renames. Both require clear source/destination, and existing destinations may be replaced. Begin with help and disposable text.'],
 ['用清单验证结果','Verify with an inventory','复制目录时应理解递归选项，不把文件复制与目录复制混为一谈。完成后列来源与目标，检查文件数和内容。课堂不要求练习递归删除；缺少文件时先定位，避免扩大操作范围。','Directory copying requires understanding recursive options. List source and destination and compare count/content afterward. Recursive deletion is not a required exercise; diagnose missing data before widening the operation.']
 ],example:['从~/academy进入linux01后，../notes表示~/academy/notes。把a.txt复制为b.txt后两者可独立修改；把b.txt改名c.txt后，原b.txt名字消失。','From ~/academy/linux01, ../notes means ~/academy/notes. Copying a.txt to b.txt creates an independent file; renaming b.txt to c.txt removes the old b.txt name.'],error:['“没有输出”不等于命令失败，许多成功命令保持安静；用目录与内容核对。','No output does not mean failure; many successful commands are quiet. Verify files and contents.'],answer:['Linux常区分大小写，因此两个名字可能对应两个不同文件。','Linux commonly distinguishes case, so the names can refer to different files.'],task:[['为C代码准备独立练习目录。','Prepare a separate C practice directory.'],['A.txt和a.txt一定是同一个文件吗？','Must A.txt and a.txt be the same file?'],['创建练习目录，复制一个文本并重命名副本，逐步ls核对。','Create a practice folder, copy text, rename its copy and verify after each step.'],['画出每一步之前和之后的目录树。','Draw before/after directory trees.'],['换一个子目录，用相对路径完成同样定位。','Repeat location using relative paths from another child.'],['提交目录树、文件内容和已执行命令。','Submit trees, contents and executed commands.'],['无误覆盖原件，能解释每个目标路径。','Preserve the original and explain every destination path.']]});

addLesson8({id:'linux-edit',area:'Linux基础',title:['文本编辑、重定向与管道','Text editing, redirection and pipes'],pre:['linux-files'],goal:['能创建UTF-8文本、查找行，并理解输出流去向。','Create UTF-8 text, find lines and explain output streams.'],refs:['linux'],sections:[
 ['纯文本适合代码和配置','Plain text for code and configuration','用纯文本编辑器保存.c或.txt，避免文字处理软件自动加入富文本格式。注意编码、换行和全角标点；代码中的英文引号、分号与括号不能用外形相似的中文符号替换。','Use a plain-text editor for .c and .txt rather than word-processing formatting. Watch encoding, line endings and full-width punctuation; similar-looking typographic quotes are not interchangeable with code punctuation.'],
 ['先学打开、保存、退出','Open, save and exit first','选择一个已安装编辑器，建立notes.txt，写三行并保存。使用nano时底部^表示Ctrl组合键，保存/退出按屏幕提示操作。再用cat检查磁盘内容，区分编辑缓冲与已保存文件。','Choose an installed editor, create notes.txt and save three lines. In nano, ^ denotes Ctrl; follow its on-screen save/exit prompts. Use cat afterward to distinguish the editing buffer from saved data.'],
 ['把输出接给文件或下一个程序','Route output deliberately','标准输出可以用>写入文件，也可用|交给下一程序。前者可能覆盖，后者传输数据流，不会自动保存。错误通常走标准错误，故只保存标准输出可能漏掉诊断信息。','Standard output can go to a file with > or to another program with |. Redirection may overwrite; a pipe transfers a stream without necessarily saving it. Errors often use standard error and may be absent from an output-only capture.'],
 ['小数据上理解搜索','Understand search on small data','在含三行的文本中用grep查找一个已知词，先预测命中行。再用wc -l数行，注意末尾换行的影响。工具输出是对输入文件的处理，不能把没有匹配理解为软件坏了。','Use grep on a three-line file and predict matches. Use wc -l to count newline characters and notice the final newline. No match is a result about input, not necessarily a broken tool.']
 ],example:['文本为alpha、beta、alphabet三行，grep alpha会选中第1和第3行。把输出写入一个新的matches.txt，原notes.txt保持不变。','For alpha, beta and alphabet on separate lines, grep alpha selects lines 1 and 3. Redirect to a new matches.txt while leaving notes.txt unchanged.'],error:['把输出重定向回同一个输入文件可能先截断它；不要用重要文件试验。','Redirecting into the same input file can truncate it before reading. Never test this on important data.'],answer:['匹配alpha的两行会留下；管道传内容，不是把两条命令同时各自运行而互不相关。','The two alpha-containing lines remain. A pipe connects content flow rather than running unrelated commands.'],task:[['从小日志中提取关心的记录。','Extract relevant records from a small log.'],['三行示例有几行包含alpha？','How many sample lines contain alpha?'],['编辑并保存三行，读取确认，搜索alpha并写入新的结果文件。','Save three lines, read them back, search alpha and write to a new result file.'],['说明输入、标准输出、标准错误和目标文件。','Identify input, stdout, stderr and destination.'],['换成包含大小写变体的文本，预测默认搜索变化。','Try case variants and predict default matching changes.'],['提交原文与筛选结果及一条无匹配记录。','Submit original/result and one no-match case.'],['结果与预测相符，原文件未被覆盖，能解释无匹配。','Match the prediction, preserve input and explain no match.']]});

addLesson8({id:'linux-permissions',area:'Linux基础',title:['用户、权限、sudo和可执行文件','Users, permissions, sudo and executables'],pre:['linux-edit'],goal:['能读基本权限并解决自己练习文件的权限问题。','Read basic permissions and diagnose your own practice-file access.'],refs:['linux'],sections:[
 ['权限分给谁','Whose permissions?','ls -l中权限分别描述所有者、组和其他用户的读写执行能力。文件的r允许读、w允许改内容、x允许尝试执行；目录的x主要表示穿越/搜索，不能机械地按文件含义理解。','ls -l reports read/write/execute permissions for owner, group and others. File r/w/x mean read, modify and attempt execution; directory x means traversal/search, so file meanings do not transfer unchanged.'],
 ['可执行标志不是安全证明','Executable does not mean trusted','脚本需要合适解释器、有效内容与必要执行权限。把任意文本chmod成可执行不会自动把它变成正确程序。./program明确指定当前目录文件；PATH通常不会自动搜索当前目录。','A script needs an interpreter, valid content and appropriate permissions. chmod does not convert arbitrary text into a working program. ./program names a file in the current directory, which is often absent from PATH.'],
 ['sudo是权限提升','sudo elevates authority','sudo按配置以另一用户身份执行命令，常用于系统管理；它不是“修复错误”按钮。先区分路径错误、语法错误和权限错误。若自己的工程由管理员创建，应查清所有权，不用chmod 777掩盖问题。','sudo runs with another user’s authority under policy, often for administration. It is not a generic repair button. Distinguish path, syntax and permission errors and investigate ownership instead of masking problems with chmod 777.'],
 ['只改自己能说明的对象','Change only an understood target','用可丢弃脚本练习查看权限，给所有者增加执行权限，然后执行并读取输出。每次写清对象路径和权限变化；系统目录与共享目录的权限属于单独管理任务，不在入门练习内。','Inspect a disposable script, add owner execute permission and run it. Record target and exact permission change. System/shared-directory permissions are administration tasks outside this beginner exercise.']
 ],example:['自己创建的hello.sh可用chmod u+x hello.sh增加所有者执行位，再./hello.sh尝试运行。若解释器路径错，即使x存在仍会失败。','For your own hello.sh, chmod u+x hello.sh adds owner execute permission; ./hello.sh attempts execution. An incorrect interpreter can still fail despite x.'],error:['所有Permission denied都加sudo会扩大影响面，也可能留下管理员拥有的工程文件。','Adding sudo to every permission error widens impact and may create administrator-owned project files.'],answer:['执行权限只是必要条件之一，解释器、路径和程序内容也必须正确。','Execute permission is only one condition; interpreter, path and program content must also be correct.'],task:[['解释一个练习脚本为什么无法运行。','Diagnose why a practice script will not run.'],['有x权限是否保证脚本正确执行？','Does x permission guarantee correct execution?'],['查看自己脚本权限，按需要只增加u+x，再运行。','Inspect your script, add only u+x if needed and run it.'],['区分权限错误和解释器/语法错误。','Distinguish permission failure from interpreter/syntax failure.'],['对另一个副本移除所有者执行位并预测变化。','Remove owner execute on another copy and predict the change.'],['提交前后权限和错误/成功输出。','Submit before/after permissions and failure/success output.'],['没有使用777或不必要sudo，能说明改变的是谁的什么权限。','Avoid 777/unneeded sudo and explain whose permission changed.']]});

addLesson8({id:'linux-packages',area:'Linux基础',title:['软件包、依赖、版本与环境隔离','Packages, dependencies, versions and isolation'],pre:['linux-permissions'],goal:['能读懂安装步骤的目的，检查软件版本并避免混用环境。','Explain setup steps, inspect versions and avoid mixing environments.'],refs:['linux','gcc','gccsetup'],sections:[
 ['软件包不只是一个程序','A package can contain more than a program','发行版软件包可包含可执行文件、库、头文件和文档。编译C时可能需要编译器及开发头文件；只有运行时库未必足够。包名、命令名和项目名不必相同。','A package may contain executables, libraries, headers and documentation. Compiling C may require compiler/development headers, not just runtime libraries. Package, command and project names need not match.'],
 ['索引刷新与安装不同','Refresh differs from installation','Ubuntu的apt update更新可用包索引；apt install才选择安装指定包，upgrade又是另一类升级动作。先阅读将安装、移除和占用空间的列表，不把网上整段系统升级当作某个小程序的必要步骤。','On Ubuntu, apt update refreshes indexes; apt install installs selected packages; upgrade changes installed versions. Read proposed changes and space requirements rather than assuming a full system upgrade is necessary for one tool.'],
 ['版本和来源一起记录','Record version and source','安装后使用工具自身的--version或对应查询命令，记录实际版本与来源。教程要求某发行版软件时，不能直接把另一发行版的源混进来；混源会造成依赖不一致。','After setup, query the tool version and source. Do not add repositories from another distribution simply because a tutorial names them; incompatible repositories can create dependency conflicts.'],
 ['一个工程一个可解释环境','Give a project an explainable environment','Python依赖可用虚拟环境隔离，ROS工作区有自己的构建与安装目录，系统包又由发行版管理。记录激活了哪个环境；命令找到了不代表来自预期环境，须核对解析路径。','Python can isolate dependencies in a virtual environment; ROS workspaces have build/install outputs; system packages remain distribution-managed. Record the active environment and resolved executable, not only whether a command exists.']
 ],example:['gcc --version显示编译器身份；command -v gcc显示当前Shell找到的位置。两项一起保存，比仅写“已装GCC”更能帮助别人复现。','gcc --version identifies the compiler; command -v gcc shows the executable found by the shell. Together they are more reproducible than “GCC installed.”'],error:['不要把更新索引、升级整个系统、安装单包和激活虚拟环境写成同一件事。','Refreshing indexes, upgrading the system, installing a package and activating an environment are different actions.'],answer:['更新索引不会自动证明目标程序已经安装，需要查包状态和实际工具版本。','An index refresh does not prove the target tool is installed; inspect package state and the actual version.'],task:[['准备一个可解释的C编译环境。','Prepare an explainable C compiler environment.'],['只运行包索引更新后，gcc一定可用吗？','Does refreshing the package index guarantee gcc is available?'],['按当前发行版官方步骤准备编译器，记录候选变更与最终版本。','Follow current distribution guidance, record proposed changes and final compiler version.'],['解释包管理器做了什么，哪些是查询操作。','Explain package changes and which steps were read-only queries.'],['新开终端复查工具路径与版本。','Recheck path/version in a fresh terminal.'],['提交环境清单和最小版本查询输出。','Submit environment inventory and version output.'],['工具来源、版本和当前路径明确，没有混用其他发行版软件源。','Identify source/version/path without mixing distribution repositories.']]});

addLesson8({id:'linux-process',area:'Linux基础',title:['进程、退出码、日志与停止程序','Processes, exit status, logs and stopping'],pre:['linux-packages'],goal:['能区分程序文件和运行进程，保存错误证据并有序停止。','Distinguish executable/process, preserve errors and stop deliberately.'],refs:['linux'],sections:[
 ['运行会产生进程','Execution creates a process','同一个程序文件可运行多次，产生不同进程。每个进程有状态、资源和标识。终端里程序持续输出不代表死机；先了解它是否设计为长期运行，如ROS节点。','One executable may run multiple times as separate processes with resources and identifiers. Continuous terminal output is not necessarily a hang; ROS nodes, for example, are often designed to keep running.'],
 ['前台停止与关闭窗口','Stop a foreground job deliberately','Ctrl+C通常向前台程序发送中断请求，程序可能清理后退出，也可能自定义处理。关闭窗口与有序停止不完全相同。先尝试程序规定退出方式，不把强制结束当默认按钮。','Ctrl+C normally requests interruption of the foreground program, which may clean up or handle it differently. Closing a window is not identical to orderly shutdown. Use the documented exit method before forcing termination.'],
 ['退出码提供一种结果信号','Exit status is one result signal','在常见Linux Shell中，命令结束后立即echo $?查看上一命令状态，0通常表示按约定成功，非0表示某种失败。具体含义由程序定义；成功退出码也不能证明算法答案正确。','In common Linux shells, echo $? immediately after a command shows its status. Zero conventionally means success and nonzero indicates failure, with meanings defined by the program. Success status does not prove correct calculations.'],
 ['日志要保留时间和上下文','Preserve log context','报错记录包括执行命令、目录、版本、首个错误、相关前后行与输入。不要只截最后一句。分享前删除令牌、用户名和设备序列号；保留足够上下文才能区分根因与连锁错误。','Record command, directory, version, first error, nearby lines and input rather than only the final sentence. Remove secrets, personal names and device identifiers before sharing, while retaining diagnostic context.']
 ],example:['一个程序因找不到input.csv返回非0。先记录当前目录与文件名，再修正路径重跑。即使第二次退出码0，仍需检查输出行数和数值。','A program returns nonzero because input.csv is missing. Record directory/filename, fix the path and rerun. Even with status zero, inspect output count and values.'],error:['没有红字不代表任务完成；最后一行错误也不一定是最先发生的根因。','No red text does not establish completion, and the last error may not be the root cause.'],answer:['进程正在运行和程序文件存在是两件事；停止一份进程不会自动删除程序文件。','A running process differs from its executable file; stopping a process does not delete the executable.'],task:[['给一个运行失败的练习程序写排错记录。','Write a diagnostic record for a failed practice run.'],['停止进程会把程序文件删除吗？','Does stopping a process delete its executable?'],['用cat读取已保存的练习文本，立即记录退出码；再给一个不存在的练习文件名，记录错误与退出码。','Use cat on a saved practice text and immediately record status; then name a nonexistent practice file and record error/status.'],['找出第一条有意义错误，说明修复依据。','Identify the first meaningful error and justify the repair.'],['重新运行并检查结果内容，而不只看退出码。','Rerun and inspect output content as well as status.'],['提交脱敏日志、原因与修复后证据。','Submit sanitized logs, cause and repair evidence.'],['另一个人能按记录重现失败与修复，原文件未损坏。','Another person can reproduce failure/repair without damaging originals.']]});

addLesson8({id:'c-first',area:'C逐步编程',title:['第一段C程序：从文本到屏幕输出','Your first C program: text to output'],pre:['linux-packages','linux-edit'],goal:['能保存、编译并运行一个输出固定文字的C程序。','Save, compile and run a C program that prints fixed text.'],refs:['c','gcc'],sections:[
 ['代码文件不是程序本身','Source is not the executable','把代码保存为hello.c，内容是人可读的源文本。编译器读取它，生成能在目标环境运行的程序。双击源文件通常只打开编辑器；把扩展名改成.exe也不等于编译。','Save source text as hello.c. A compiler translates it into a program for the target environment. Opening source usually opens an editor; changing its extension does not compile it.'],
 ['从main开始理解','Begin with main','在本课普通宿主程序中，int main(void)是程序入口。花括号围住函数体，分号结束语句；return 0向运行环境报告成功结束。先对照成对括号，不急着背全部语法。','In this ordinary hosted example, int main(void) is the entry function. Braces enclose its body, semicolons terminate statements and return 0 reports successful termination. First match the delimiters.'],
 ['输出需要库声明','Printing needs a declaration','#include <stdio.h>提供标准输入输出函数的声明。puts("Hello, C!")输出字符串并换行；双引号中的文字是数据，不是变量名。英文引号不能替换成排版弯引号。','Including stdio.h declares standard I/O functions. puts("Hello, C!") prints a string with a newline. Quoted text is data, not a variable name; typographic quotes are not equivalent code punctuation.'],
 ['保存、编译、运行三步','Save, build and run','在hello.c所在练习目录，用gcc -std=c17 -Wall -Wextra hello.c -o hello编译，再./hello运行。这里选择Linux/GCC参考环境；网页不会替你执行。修改文字后必须保存并重新编译才会更新可执行文件。','In the practice directory, compile using gcc -std=c17 -Wall -Wextra hello.c -o hello, then run ./hello. This uses Linux/GCC externally. Save and rebuild after changing the text; the webpage does not execute it.']
 ],example:['完整代码：\n#include <stdio.h>\nint main(void) {\n    puts("Hello, C!");\n    return 0;\n}\n预期输出一行Hello, C!。','Complete source:\n#include <stdio.h>\nint main(void) {\n    puts("Hello, C!");\n    return 0;\n}\nExpect one line: Hello, C!'],error:['修改源码但没有重新编译时，运行的仍可能是上一次程序。','Editing source without rebuilding may still run the previous executable.'],answer:['源代码改变不会自动改变旧可执行文件，必须保存并成功重新构建。','Changed source does not automatically update an existing executable; save and rebuild successfully.'],task:[['制作能显示自己课程编号的第一个程序。','Build a first program displaying your course identifier.'],['只改源码不编译，旧程序输出会变吗？','Will an old executable change after source edits alone?'],['输入完整代码，保存、编译、运行；把输出改为Lesson 01并重做。','Enter, save, build and run the full source; change output to Lesson 01 and repeat.'],['逐个解释include、main、puts、return的位置和作用。','Explain include, main, puts and return.'],['新增第二条puts，先预测行数再运行。','Add a second puts, predict line count and run.'],['提交源码、编译命令和两次输出。','Submit source, build command and both outputs.'],['能从空目录重建，输出与预测相符且没有编译警告。','Rebuild from an empty practice directory with expected output and no warnings.']]});

addLesson8({id:'c-build',area:'C逐步编程',title:['编译错误、链接错误与旧程序','Compile errors, link errors and stale binaries'],pre:['c-first'],goal:['能按错误发生阶段排查，而不是随机修改代码。','Diagnose failures by stage rather than random edits.'],refs:['gcc'],sections:[
 ['编译经过几个阶段','Build stages','预处理处理include等指令，编译和汇编生成目标代码，链接把目标文件与需要的库组合。一个.c能通过语法检查，不代表链接时一定找到所有函数定义。','Preprocessing handles includes, compilation/assembly produce object code and linking combines objects/libraries. Passing source syntax does not guarantee every function definition is available to the linker.'],
 ['先看第一条有用错误','Read the first useful diagnostic','漏分号可能使编译器在下一行才报告错误，因此行号指向的是发现异常处，未必是根因。先读文件名、行号、消息，再检查附近语句；修一处后重新编译，避免同时改很多无关位置。','A missing semicolon may be reported on the next line, where the issue becomes visible. Read file/line/message and nearby code, repair one cause and rebuild rather than changing many unrelated lines.'],
 ['声明和定义不同','Declaration versus definition','函数声明告诉编译器名字和参数，定义提供实现。声明了int add(int,int)却没有链接实现，可能出现undefined reference。程序名字拼错则是Shell找不到可执行文件，是另一层问题。','A declaration gives a name and signature; a definition supplies behavior. Declaring add without linking its implementation can yield undefined reference. A misspelled executable name is a separate shell lookup failure.'],
 ['失败后不要运行旧成果','Avoid stale outputs','构建失败时旧hello可能还在。先记录构建退出码，只有成功后才运行新结果；输出内容最好包含本次可辨识版本标记。警告也要理解，不能用关闭警告替代修正。','A failed build may leave an older hello. Check build status and run only after success, using a recognizable version marker. Understand warnings rather than disabling them as a substitute for repairs.']
 ],example:['删掉puts语句末尾分号会导致构建失败。恢复分号后重新编译，再运行新文字；如果失败时仍运行hello，看到旧文字不能证明错误已修复。','Removing the semicolon after puts causes a build failure. Restore it, rebuild and run new text. Seeing old output from an existing hello during a failed build proves nothing about the repair.'],error:['错误数量多可能由一个早期语法错误引起，不能按数量判定程序彻底损坏。','Many diagnostics can cascade from one early error; count alone does not measure damage.'],answer:['文件可能仍是旧版本；要用构建成功状态与新版本输出共同确认。','The executable may be stale; confirm both successful build status and new output.'],task:[['把一个缺分号的示例修好并证明运行的是新版本。','Repair a missing-semicolon example and prove it is the new binary.'],['构建失败后hello仍存在，这能证明构建成功吗？','Does an existing hello prove success after a failed build?'],['在副本中删分号，保存第一条错误；修复并改输出标记后重建。','Remove a semicolon in a copy, record the first diagnostic, repair and rebuild with a changed marker.'],['给三类失败贴标签：源码语法、链接、命令路径。','Classify syntax, linking and command-path failures.'],['交换两个字母造成名字错误，再用同一流程定位。','Introduce a transposed name and diagnose with the same process.'],['提交错误片段、修复差异及成功输出。','Submit diagnostic excerpt, repair difference and successful output.'],['能说明根因且没有把旧二进制当作新构建。','Explain the cause without mistaking a stale binary for a new build.']]});

addLesson8({id:'c-values',area:'C逐步编程',title:['变量、类型、赋值和输出格式','Variables, types, assignment and formatting'],pre:['c-build'],goal:['能用合适类型保存计数和测量，并追踪变量变化。','Choose types for counts/measurements and trace updates.'],refs:['c'],sections:[
 ['变量有名字、类型和值','A variable has type and value','int count=3声明一个整数变量并初始化为3。名字帮助人理解用途，类型约束表示和运算；未初始化的自动局部变量不能直接当0使用。每个物理量还应记录单位，类型本身不区分米和毫米。','int count=3 declares and initializes an integer. Type constrains representation/operations; an uninitialized automatic local must not be assumed zero. Physical units need separate documentation because type alone does not distinguish meters from millimeters.'],
 ['赋值不是数学等式','Assignment changes state','count=count+1先取旧count，计算加1，再写回，因此3变4。左边必须是可修改对象，右边是表达式。程序按执行顺序改变状态，不是把等号当永久成立的代数关系。','count=count+1 reads the old value, adds one and stores the result, changing 3 to 4. Assignment updates state in execution order rather than asserting a permanent mathematical equality.'],
 ['整数和小数各有边界','Integer and floating representations','int适合可表示范围内的整数，double适合许多近似实数运算；不能假设所有机器的int位宽相同。double也不是无限精度，0.1等十进制小数通常无法精确表示。','int stores integers within its implementation’s range; double supports many approximate real calculations. Do not assume every int has the same width. double is finite precision and generally cannot represent decimal 0.1 exactly.'],
 ['输出格式必须匹配','Match printf formats','printf("%d\\n",count)输出int；printf("%.2f\\n",voltage)以两位小数输出double。格式与参数类型必须匹配。小数位数改变显示，不会让测量本身更准确。','printf("%d\\n",count) prints an int; printf("%.2f\\n",voltage) prints double to two decimal places. Match format and argument type. Display digits do not improve measurement accuracy.']
 ],example:['int count=3; double voltage=2.5; count=count+1; 执行后count=4，voltage仍为2.5。输出可写printf("%d %.2f\\n",count,voltage)，预期4 2.50。','After int count=3; double voltage=2.5; count=count+1;, count is 4 and voltage remains 2.5. printf("%d %.2f\\n",count,voltage) gives 4 2.50.'],error:['变量名叫voltage并不会自动把mV换成V，必须明确单位换算。','Naming a variable voltage does not automatically convert mV to V.'],answer:['count变4，voltage不变，因为只给count重新赋值。','count becomes 4 while voltage is unchanged because only count is assigned.'],task:[['记录样本编号和电压。','Record a sample index and voltage.'],['例题执行后两个变量各是多少？','What are both variables after the example?'],['把例题放入main并输出，逐句记录值表。','Place the example in main and print it while tracing values statement by statement.'],['解释初始化与后续赋值的区别。','Explain initialization versus later assignment.'],['增加一个温度double和单位标签，改变显示位数。','Add a temperature double with units and vary display precision.'],['提交代码、逐句值表和带单位输出。','Submit code, value trace and unit-labeled output.'],['格式匹配且无未初始化读取，单位明确。','Match formats, avoid uninitialized reads and label units.']]});

addLesson8({id:'c-arithmetic',area:'C逐步编程',title:['算术、整数除法、单位与范围','Arithmetic, integer division, units and range'],pre:['c-values'],goal:['能预测整数/浮点除法，并先换单位再计算。','Predict integer/floating division and convert units before calculation.'],refs:['c'],sections:[
 ['操作数决定除法规则','Operands determine division','5/2两个操作数都是int，结果为整数2；5.0/2含浮点操作数，结果2.5。把5/2的结果事后存入double只会得到2.0，已经丢失的小数不会回来。','5/2 uses integer operands and gives 2; 5.0/2 gives 2.5. Assigning the result of 5/2 to double produces 2.0 and cannot restore the discarded fraction.'],
 ['括号让意图清楚','Parentheses clarify intent','电流计算应先求电阻电压再除阻值：(supply-led)/resistance。supply-led/resistance是另一个表达式。把计算拆成中间变量，既便于检查，也能标记每一步单位。','Current uses (supply-led)/resistance; supply-led/resistance means something else. Intermediate variables help inspection and make units explicit at each step.'],
 ['单位换算是算法的一部分','Units belong to the algorithm','330Ω与3V计算得到安培，显示mA需乘1000。10kΩ要先变10000Ω；不要让变量数字相同而单位偷偷变化。用变量名后缀_mV、_V或注释表明约定。','3 V divided by 330 Ω gives amperes; multiply by 1000 for mA. Convert 10 kΩ to 10000 Ω. Use suffixes or comments so a numeric value does not silently change units.'],
 ['除零与溢出先检查','Check division and range','除数0不是可忽略的小误差。带符号整数溢出不保证按二进制回绕；在运算前选择足够范围或检测边界。浮点结果也需判断是否有限，不能只看打印了一个数字。','Zero divisors require handling. Signed integer overflow is not guaranteed to wrap; choose adequate range or test boundaries before arithmetic. Floating results also need validity checks, not merely printable output.']
 ],example:['double i_mA=(5.0-2.0)/330.0*1000.0; 得约9.09。若用int i=(5-2)/330，结果为0，再乘1000仍为0。','double i_mA=(5.0-2.0)/330.0*1000.0 gives about 9.09. int i=(5-2)/330 gives zero; multiplying later still gives zero.'],error:['“最后变量是double”不意味着前面的整数运算自动变成浮点。','A double destination does not automatically make earlier integer operations floating-point.'],answer:['前者整数除法得0，后者浮点运算得到约9.09mA。','The integer expression yields zero; the floating expression gives about 9.09 mA.'],task:[['为LED回路写一个单位明确的计算程序。','Write a unit-aware LED calculation.'],['两种例题写法会得到相同电流吗？','Do the two example expressions give the same current?'],['并排计算整数版与浮点版，再用手算核对。','Compute both integer and floating versions and compare with hand calculation.'],['说明小数在哪一步丢失，标出每个量的单位。','Identify where the fraction is lost and label units.'],['把电源改8V、电阻改680Ω，先手算再运行。','Change supply to 8 V and resistance to 680 Ω; predict then run.'],['提交两组输入、单位和预期/实际结果。','Submit two input sets, units and expected/actual values.'],['能解释差异并对0Ω输入定义拒绝处理。','Explain the difference and define rejection of 0 Ω input.']]});

addLesson8({id:'c-input',area:'C逐步编程',title:['读入数字与验证输入','Reading numbers and validating input'],pre:['c-arithmetic'],goal:['能识别输入失败、范围不合法和有效值三种状态。','Distinguish parse failure, invalid range and valid input.'],refs:['c'],sections:[
 ['输入文字先要解析','Text must be parsed','键盘输入的字符不自动成为可靠数值。scanf("%d",&count)尝试读取整数，返回成功赋值的项数；读1个整数时应检查返回值是否为1，再使用count。&的具体内存含义将在指针课展开。','Typed characters are not automatically trustworthy numbers. scanf("%d",&count) attempts an integer and returns the number assigned. Check for 1 before using count; pointer/address details come later.'],
 ['解析成功仍可能不合法','Parsed does not mean valid','输入−5可以是合法整数，但若表示样本数量就可能超出允许范围。把语法解析、业务范围和物理合理性分开。课堂允许样本数1到10时，0和11都应拒绝。','−5 is a valid integer representation but may be invalid as a sample count. Separate parsing, application bounds and physical plausibility. For a 1–10 sample rule, reject both 0 and 11.'],
 ['失败路径也需要定义','Define failure behavior','若只读一次，失败时输出清楚错误并结束即可。反复scanf读到同一个非法字符可能陷入失败循环，因为失败字符仍留在输入流。后续更稳健方案是读整行再解析，并检查尾部内容与范围。','For a one-shot exercise, report an error and exit. Repeated scanf on the same invalid character may keep failing because it remains in the stream. Robust later designs read a line, parse and check trailing content/range.'],
 ['先限定课堂输入','State the exercise scope','本课scanf示例只接受简单、可表示范围内的整数，不能宣称已处理任意恶意或超长输入。现实工具可用fgets加strtol，检查转换结束位置、错误和目标范围，再接受结果。','This scanf exercise accepts simple integers within representation range, not arbitrary hostile or oversized input. Practical tools can use fgets/strtol with end-pointer, error and range checks.']
 ],example:['int count=0; if (scanf("%d",&count)!=1) { puts("invalid input"); return 1; } 对输入7继续；输入hello走错误分支。之后还要判断count是否在1到10。','int count=0; if (scanf("%d",&count)!=1) { puts("invalid input"); return 1; } accepts parsing 7 and rejects hello. Then check count lies from 1 to 10.'],error:['不能忽略读取返回值，也不能把“能解析”当成“符合业务范围”。','Do not ignore input status or equate parsing with application validity.'],answer:['hello不能赋给整数，应走解析错误；0虽可解析，但不在1到10内。','hello is a parse failure; zero parses but is outside 1–10.'],task:[['读取一个有限范围的样本数量。','Read a bounded sample count.'],['输入hello与0应属于同一错误吗？','Are hello and zero the same kind of error?'],['实现单次读取并分别测试7、hello、0、11。','Implement one-shot input and test 7, hello, 0 and 11.'],['把四个结果按解析/范围/有效分类。','Classify parse failure, range failure and valid input.'],['把允许范围改2到5，更新边界用例。','Change the range to 2–5 and update boundary tests.'],['提交四类输入输出与范围约定。','Submit input/output cases and the range contract.'],['读取失败后不使用旧值，范围边界均有测试。','Never use a stale value after parse failure; test both boundaries.']]});

addLesson8({id:'c-conditions',area:'C逐步编程',title:['条件、比较、逻辑与边界','Conditions, comparisons, logic and boundaries'],pre:['c-input'],goal:['能从要求写出无重叠无遗漏的条件分支。','Translate a requirement into complete, nonoverlapping branches.'],refs:['c'],sections:[
 ['比较产生判断结果','Comparisons produce conditions','==比较是否相等，=是赋值；<、<=的边界不同。if括号里表达式为0视为假，非0为真。把voltage=5误写在条件中可能改变变量，而不是检查它。','== compares equality; = assigns. < and <= differ at the boundary. An if condition treats zero as false and nonzero as true. An assignment in a condition can change a variable instead of testing it.'],
 ['区间需要两次比较','Intervals require two comparisons','1<=count && count<=10表示闭区间。C里不能照抄数学写法1<=count<=10：前半比较先得到0或1，再与10比较。&&为且，||为或，!取逻辑反。','Use 1<=count && count<=10 for an inclusive interval. In C, 1<=count<=10 compares the first Boolean result against 10. && means AND, || OR and ! logical NOT.'],
 ['分支顺序会影响结果','Branch order matters','把温度分为低于0、0到50、超过50三个区间，可用if、else if、else。先写清0与50属于哪一类，再检查每个输入是否恰好落入一类；不要让两个独立if产生相互矛盾输出。','For below 0, 0–50 and above 50, use if/else if/else and define ownership of 0 and 50. Ensure each input belongs to one category and avoid contradictory outputs from independent conditions.'],
 ['短路求值可保护后续运算','Short-circuit evaluation','&&左侧为假时右侧不执行，可先检查分母非0再计算比值。||左侧为真时右侧不执行。不要把必要副作用藏在可能跳过的条件中，初学先保持条件只做判断。','With &&, a false left side skips the right; with ||, a true left side skips the right. This can guard division, but avoid hiding required side effects in a condition that may be skipped.']
 ],example:['if (count>=1 && count<=10)打印accepted，否则打印range error。输入1、10应接受，0、11应拒绝；这四点覆盖两个边界的内外两侧。','if (count>=1 && count<=10) accepts 1 and 10 and rejects 0 and 11. These four cases cover inside/outside at both boundaries.'],error:['1<=x<=10在C中不是数学区间判断。','1<=x<=10 is not a mathematical interval test in C.'],answer:['1和10包含在闭区间，0与11不包含；必须用两个比较和&&连接。','The inclusive interval contains 1 and 10, not 0 or 11; combine two comparisons with &&.'],task:[['给传感器输入设计范围检查。','Design range validation for sensor input.'],['闭区间1到10会接受哪些边界点？','Which boundary values does inclusive 1–10 accept?'],['编写分支并测试0、1、10、11，保存输出。','Implement branches and test 0, 1, 10 and 11.'],['说明=与==、<与<=的区别。','Explain = versus == and < versus <=.'],['增加“恰好上限”的单独提示且不重复输出。','Add a distinct upper-bound message without duplicate output.'],['提交分支图和边界表。','Submit a branch diagram and boundary table.'],['所有合法输入只有一个结果，边界与题意一致。','Every valid input has exactly one outcome with correct boundaries.']]});

addLesson8({id:'c-loops',area:'C逐步编程',title:['循环、计数与终止条件','Loops, counters and termination'],pre:['c-conditions'],goal:['能逐轮追踪for/while，发现少一次、多一次和不终止。','Trace loops and identify off-by-one and termination errors.'],refs:['c'],sections:[
 ['for把三件事放在一起','Three parts of for','for初始化只在开始执行一次，条件在每轮体前检查，更新在每轮体后执行。for(int i=0;i<3;i++)的循环体看到i为0、1、2，不会看到3。','A for initializer runs once, the condition precedes each body and the update follows it. for(int i=0;i<3;i++) enters the body with 0,1,2, not 3.'],
 ['累加器先给初值','Initialize the accumulator','求1到5之和时sum从0开始，每轮加i。把sum=0放进循环体会每次清空，最终只剩最后一项。逐行值表比盯着最终输出更容易发现错误。','For summing 1–5, initialize sum to zero before the loop and add i each iteration. Resetting sum inside the body discards previous terms. A trace table reveals this better than final output alone.'],
 ['while先问能否继续','while checks before entry','while适合重复直到条件变化，但循环体必须推动状态接近终止。条件一开始为假时执行0次；do-while至少执行1次。等待外部设备时还需要超时，不允许无期限卡住全部工作。','while repeats while a condition holds, and progress must move toward termination. An initially false condition gives zero iterations; do-while runs at least once. Device waits also need timeouts rather than indefinite blocking.'],
 ['为零次与最后一次写测试','Test zero and final iterations','测试计数0、1和若干次。数组长度为N时常用i<N，i<=N会多访问一项。break退出最近一层循环，continue跳过本轮剩余体，不应让它跳过唯一的计数更新。','Test counts zero, one and several. For N array elements, i<N is typical; i<=N adds an out-of-bounds access. break exits the nearest loop; continue skips the remaining body and must not bypass the only progress update.']
 ],example:['int sum=0; for(int i=1;i<=5;i++){sum+=i;} 各轮sum为1、3、6、10、15。把上限改0则循环体不执行，sum仍0。','int sum=0; for(int i=1;i<=5;i++){sum+=i;} produces sums 1,3,6,10,15. With upper bound zero, the body never runs and sum stays zero.'],error:['循环次数与最后的计数值并不总是相同，先列进入体时的值。','Iteration count is not always the final counter value; list values seen in the body.'],answer:['循环体看到0、1、2，共3次；3是失败条件检查时的值。','The body sees 0,1,2: three iterations. Three is the failing condition value.'],task:[['写一个可核对的累计采样计数器。','Write a verifiable accumulation loop.'],['i从0且条件i<3，循环体会运行几次？','How many body executions for i=0 and i<3?'],['打印每轮i与sum，再测试上限0、1、5。','Print i and sum each iteration and test bounds 0, 1 and 5.'],['定位把初始化放进循环的错误。','Diagnose resetting the accumulator inside the loop.'],['改为累加偶数，先写预期序列再运行。','Change to summing even numbers, predicting the sequence first.'],['提交逐轮表与零次测试。','Submit traces and a zero-iteration test.'],['计数、和与终止全部正确，没有越界或无限循环。','Get count, sum and termination right without overflowed bounds or infinite loops.']]});

addLesson8({id:'c-functions',area:'C逐步编程',title:['函数、参数、返回值与局部变量','Functions, parameters, returns and local variables'],pre:['c-loops'],goal:['能把一段计算封装成可测试函数并说明输入输出。','Package a calculation as a testable function with defined inputs/outputs.'],refs:['c'],sections:[
 ['给重复计算取名字','Name a reusable calculation','函数把输入映射到结果或明确副作用。先写契约：电流函数接受电压差V和电阻Ω，返回A，电阻必须正数。这样调用者不用每次重新猜测单位与允许值。','A function maps inputs to outputs or explicit side effects. Define a contract: voltage difference in V, positive resistance in Ω and current in A. Callers then know units and valid inputs.'],
 ['参数是本次调用的局部值','Parameters are local values','double current(double v,double r)接收参数值的副本。在函数内给v重新赋值不会直接改变调用者的普通double变量；需要改变外部对象时会涉及指针和明确接口。','double current(double v,double r) receives copies of argument values. Assigning v inside does not directly alter a caller’s ordinary double. Modifying caller objects requires a different, explicit interface such as pointers.'],
 ['return结束这次调用','return ends the call','return v/r把结果交给调用处，并结束当前调用。返回后才写的语句不会执行。非void函数的有效路径应按契约返回值，不能靠某次测试恰好得到数字来掩盖缺少返回。','return v/r sends a result to the caller and ends that invocation. Later statements do not run. Valid paths in a non-void function need defined returns rather than accidental values observed in one test.'],
 ['先单独测试再组合','Test before composition','用已知输入测试函数，例如3V/330Ω；再测试另一正常值和禁止值的处理。把显示与计算分开：函数返回A，main负责转mA打印，可避免显示习惯污染核心计算。','Test a known case such as 3 V/330 Ω, another valid case and handling of forbidden input. Separate computation from printing: return A and convert to mA in main.']
 ],example:['double current(double v,double r){return v/r;} 在调用前确认r>0。current(3.0,330.0)*1000约9.09，current(6.0,330.0)*1000约18.18。','double current(double v,double r){return v/r;} requires checking r>0 before calling. current(3.0,330.0)*1000 is about 9.09; using 6 V gives about 18.18.'],error:['函数里的局部变量不会因同名就与main里的变量成为同一个对象。','A local variable is not the same object as a same-named variable in main.'],answer:['普通数值参数按值传递，改变参数副本不会直接改变调用者变量。','Ordinary numeric arguments are passed by value; changing the copy does not directly change the caller’s variable.'],task:[['把LED电流计算从main拆成函数。','Extract LED current calculation from main.'],['函数内修改v会直接修改main中的同名变量吗？','Will changing parameter v modify a same-named main variable?'],['写明契约，实现函数并测试两个已知电压和禁止的0Ω。','Define the contract, implement and test two voltages plus rejected zero resistance.'],['解释实参、形参、返回值与局部变量。','Explain arguments, parameters, return and locals.'],['新增功率函数并独立测试，再组合显示。','Add/test a power function before combining output.'],['提交函数契约和测试表。','Submit contracts and test table.'],['单位一致，禁止输入有明确路径，结果可独立验证。','Keep units consistent, define invalid-input behavior and verify results independently.']]});

addLesson8({id:'c-arrays',area:'C逐步编程',title:['数组、下标、长度与遍历','Arrays, indices, length and traversal'],pre:['c-functions'],goal:['能存一组样本并在有效下标内求和、均值与极值。','Store samples and compute sum/mean/extrema within valid indices.'],refs:['c'],sections:[
 ['一组同类型对象','A sequence of same-type elements','double samples[3]={1.0,2.0,3.0}创建三个元素，下标0、1、2。长度3不是最后下标3。C数组不会自动在越界时弹出提示；读写samples[3]已经越过这个数组。','double samples[3]={1.0,2.0,3.0} has indices 0,1,2. Length three is not last index three. C does not guarantee an automatic bounds error when samples[3] is accessed.'],
 ['遍历依靠长度约定','Traversal needs a length','for循环常用i<n，n必须与实际元素数一致。数组传给函数时通常不自动携带长度，接口应另传元素数。不要用函数参数上的sizeof猜原数组总长度。','Use i<n with a length matching the actual array. Array arguments generally do not carry their length automatically, so pass it explicitly. sizeof on an array-style function parameter does not recover the original array size.'],
 ['均值先处理空集合','Handle an empty set','先累加再除以n，n=0时不能计算均值。极值可从第一个有效元素初始化，避免用0导致全负数或全正数数据错误。长度与有效样本数也可能不同。','Compute sum then divide by n, but define the n=0 case. Initialize extrema from a real first element rather than zero. Allocated capacity and valid sample count can differ.'],
 ['修改输入也是契约','Mutating input is part of the contract','只读处理可通过const参数表达不修改元素的意图，但仍要确保访问范围合法。需要排序时说明是否原地改变数组；保留原始测量比覆盖它更利于复核。','A const-qualified input expresses no element modification but does not guarantee bounds. State whether sorting is in-place. Preserve original measurements when later verification matters.']
 ],example:['对[1,2,3]遍历下标0到2，sum=6，mean=2。测试[-3,-2,-1]时最大值应为−1；若初始化max=0，会产生不存在于数据中的错误结果。','For [1,2,3], indices 0–2 give sum 6 and mean 2. For [-3,-2,-1], maximum is −1; initializing max to zero incorrectly invents a larger value.'],error:['容量、有效元素数、最后下标是三个不同数字或概念。','Capacity, valid count and last index are different concepts.'],answer:['三个元素的最后有效下标是2，必须保持i<3。','The last valid index of three elements is 2; keep i<3.'],task:[['统计一小组电压样本。','Summarize a small voltage sample set.'],['长度3的数组能访问下标3吗？','May a length-three array access index three?'],['计算三组数据的和、均值、最大值：正数、负数、单元素。','Compute sum, mean and maximum for positive, negative and single-element sets.'],['逐个标出被访问下标并解释空数据处理。','List accessed indices and explain the empty-set policy.'],['把统计写成显式接收长度的函数。','Move statistics into functions receiving explicit length.'],['提交数组、长度、手算及程序结果。','Submit arrays, lengths and hand/program results.'],['没有越界，负数和单元素正确，空数据不除零。','Avoid bounds errors and divide-by-zero; handle negative/single-element cases.']]});

addLesson8({id:'c-strings',area:'C逐步编程',title:['字符、字符串结尾与缓冲区','Characters, string termination and buffers'],pre:['c-arrays'],goal:['能区分字符与字符串，给结束符留空间并限制读取。','Distinguish characters/strings, reserve terminator space and bound input.'],refs:['c'],sections:[
 ['字符不是字符串','Character versus string','单引号中的A表示字符常量，双引号中的A表示含字符A和结尾零字符的字符串。char name[4]="LED"需要L、E、D、\\0四个位置；结尾\\0不是数字字符0。','A single-quoted A is a character constant; double-quoted A is a string with a terminating zero character. char name[4]="LED" stores L,E,D and \\0. The terminator differs from the digit character 0.'],
 ['容量要包含结尾','Capacity includes termination','最多保存3个可见ASCII字符的C字符串至少需4个char。字符串函数常从起点读到零字符，如果数组没有终止就可能越界。打印前知道长度和是否有结尾，不靠运气找到内存里的0。','Three visible ASCII characters need at least four char slots as a C string. Many string functions read until zero and can overrun unterminated arrays. Know the bounds and termination before printing.'],
 ['整行输入还可能带换行','Line input may include newline','fgets(buffer,sizeof buffer,stdin)在成功时限制写入长度并添加零字符，但可能保留换行，超长行可能只读一部分。检查返回值，判断是否读全，不能把截断片段误当完整命令。','On success, fgets bounds the read and terminates the result, but can retain newline or read only part of a long line. Check its return and whether the line is complete before accepting a command.'],
 ['字节数不一定是字数','Bytes are not always characters','UTF-8中文通常占多个字节，strlen数的是零字符前的字节数，不是汉字个数。本节先用ASCII练习，随后面对中文时明确编码，不按任意字节位置剪断多字节字符。','UTF-8 characters can occupy multiple bytes. strlen counts bytes before the terminator, not Chinese characters. Start with ASCII and later handle encoding deliberately rather than cutting multibyte text at arbitrary byte offsets.']
 ],example:['char label[4]="LED"的sizeof为4、strlen为3。数组[3]中是\\0；若把[3]改成X且没有其他空间，就不再是正确终止的这个字符串。','char label[4]="LED" has sizeof 4 and strlen 3. Index 3 holds \\0; replacing it with X without extra space removes valid termination.'],error:['字符0、数值0和字符串结尾在源码写法与用途上不同。','The digit character, numeric zero and string terminator have different spellings/roles.'],answer:['需要4个char，因为3个字母之外还要结尾零字符。','Four char slots are needed: three letters plus the zero terminator.'],task:[['为传感器名称设置有限文本输入。','Read a bounded sensor label.'],['LED作为C字符串最少占几个char？','How many char slots does LED need as a C string?'],['保存LED并比较sizeof与strlen；用fgets读取短行并检查返回。','Store LED, compare sizeof/strlen and read a short line with fgets checking status.'],['解释容量、已用字节和结尾位置。','Explain capacity, used bytes and terminator position.'],['输入超过容量的ASCII行，识别截断而非越界写入。','Enter an oversized ASCII line and detect truncation instead of overrunning.'],['提交内存格图、代码和短/长输入结果。','Submit a buffer diagram, code and short/long input results.'],['终止明确，长度受限，能识别未读完的行。','Maintain termination/bounds and recognize incomplete lines.']]});

addLesson8({id:'c-pointers',area:'C逐步编程',title:['指针、地址、间接访问与生命周期','Pointers, addresses, indirection and lifetime'],pre:['c-arrays','c-functions'],goal:['能画对象与指针关系，使用有效地址修改一个对象。','Draw object/pointer relationships and modify an object through a valid address.'],refs:['c'],sections:[
 ['地址指向对象','An address refers to an object','int value=7; int *p=&value; 中value是整数对象，&value取得它的地址，p存这个地址。p的值不是7；*p才通过地址访问value。星号在声明与表达式中承担相关但不同角色。','In int value=7; int *p=&value;, value is an integer object, & obtains its address and p stores that address. p is not the integer seven; *p accesses the referenced object.'],
 ['通过同一对象观察变化','Observe shared object identity','执行*p=9改变的是value，之后value和*p都读到9。把p重新指向另一个变量则改变“指向谁”，不是移动原对象。画箭头比把指针当神秘数字更容易理解。','Assigning *p=9 changes value, so both reads produce 9. Reassigning p to another variable changes which object is referenced, not the object’s location. Draw arrows between pointer and object.'],
 ['有效地址还需要有效生命期','Validity includes lifetime','局部变量在作用域结束后不再有效，不能返回它的地址再解引用。NULL表示没有有效对象供当前指针访问，但并非所有坏指针都等于NULL。类型转换也不能修复悬空地址。','A local object expires when its lifetime ends; returning its address and dereferencing later is invalid. NULL denotes no object for access, but not every invalid pointer is NULL. Casting does not repair dangling storage.'],
 ['边界与写入权限仍适用','Bounds and mutability remain','指向数组时只访问对象范围内元素；尾后指针可用于比较和遍历结束，但不能解引用。通过指针修改调用者变量时，把是否允许NULL、对象个数和生命周期写入函数契约。','For arrays, remain within object bounds. A one-past pointer can mark the end but cannot be dereferenced. Pointer-based interfaces should specify nullability, element count and required lifetime.']
 ],example:['void set_zero(int *p){*p=0;} 只在p指向有效可写int时调用。int n=5; set_zero(&n); 后n为0；把普通数值5当地址传入则不满足契约。','void set_zero(int *p){*p=0;} requires a valid writable int. With int n=5; set_zero(&n);, n becomes zero. Supplying numeric five as an address violates the contract.'],error:['指针不是自动扩容容器，非NULL也不能证明地址有效。','A pointer is not an automatically sized container, and non-NULL does not prove validity.'],answer:['*p=9改变p指向的value，所以value变9，p仍指向同一对象。','*p=9 changes the referenced value to nine while p still points to that object.'],task:[['让函数重置调用者的计数器。','Reset a caller’s counter through a function.'],['*p=9后，value与p分别发生什么变化？','What changes in value and p after *p=9?'],['画内存关系，再实现有效int对象上的set_zero并运行。','Draw relationships, implement set_zero for a valid int and run.'],['解释按值参数和指针参数都传值但效果为何不同。','Explain why both pass values yet a pointer permits indirect modification.'],['扩展为两个输出对象，并检查它们的地址与生命周期。','Extend to two output objects and check addresses/lifetimes.'],['提交箭头图、函数契约和执行前后值。','Submit a pointer diagram, contract and before/after values.'],['没有返回局部地址或解引用无效对象，能指出真正被修改的对象。','Avoid dangling dereferences and identify the actual modified objects.']]});

addLesson8({id:'c-structs',area:'C逐步编程',title:['结构体：把一次测量的数据放在一起','Structures: grouping a measurement'],pre:['c-pointers'],goal:['能用结构体表示值、时间与有效性，不混淆不同样本。','Represent value, time and validity together without mixing samples.'],refs:['c'],sections:[
 ['相关字段属于同一记录','Related fields form one record','只保存电压会丢失何时测得、是否有效等信息。struct Sample可含double voltage、unsigned sequence、int valid。每个成员仍有自己的类型，结构体把这些字段作为一个逻辑记录管理。','A voltage alone lacks age and validity. struct Sample can hold double voltage, unsigned sequence and int valid. Each member retains its type while the structure groups them as a logical record.'],
 ['点访问与箭头访问','Dot and arrow access','对象s用s.voltage访问成员；指向对象的p用p->voltage，等价于(*p).voltage。先保证p有效，再访问字段。字段名描述物理意义，单位写入名称或接口说明。','Use s.voltage on an object and p->voltage on a pointer, equivalent to (*p).voltage. Validate the pointer first. Member names and interface documentation should make units clear.'],
 ['复制记录不等于深复制','Record copies can be shallow','普通结构体赋值复制成员值。若成员是数组会复制其元素；若成员是指针，只复制地址，不复制所指缓冲区。不要把两个指向同一缓冲区的记录当作两个独立数据副本。','Structure assignment copies member values. Array members are copied, while pointer members copy addresses, not pointed-to buffers. Two records sharing one buffer are not independent deep copies.'],
 ['不要直接把内存当协议','Memory layout is not a wire format','结构体可能存在填充、对齐与字节序差异。把sizeof(struct)字节直接发送到另一平台，不保证对方按相同方式读取。明确字段长度、单位、顺序和编码再序列化。','Padding, alignment and endianness can vary. Sending raw sizeof(struct) bytes does not guarantee another platform interprets them identically. Define field sizes, units, ordering and encoding explicitly.']
 ],example:['struct Sample { double voltage; unsigned sequence; int valid; }; struct Sample s={2.5,3,1}; 表示第3号有效样本2.5V。将valid改0后，数值仍存在但不应当作可信新测量。','struct Sample { double voltage; unsigned sequence; int valid; }; struct Sample s={2.5,3,1}; represents valid sample 3 at 2.5 V. Setting valid=0 leaves a number but removes its accepted-measurement status.'],error:['数值看起来正常不代表测量有效，时间和有效标志必须一起传递。','A plausible number is not necessarily valid; preserve timing and validity.'],answer:['valid变0后应走无效数据处理，而非继续把2.5V当可靠新样本。','When valid becomes zero, use invalid-data handling rather than treating 2.5 V as a reliable new sample.'],task:[['建立三条带有效标志的采样记录。','Create three sample records with validity.'],['valid=0但电压仍2.5，这条记录能直接用于控制吗？','Can a record with valid=0 and voltage 2.5 directly drive control?'],['定义结构体，填三条记录，只统计有效记录。','Define a structure, fill three records and aggregate only valid entries.'],['解释对象成员与指针成员访问方式。','Explain object/pointer member access.'],['增加时间字段并拒绝超龄记录。','Add age information and reject stale records.'],['提交记录表、有效数和聚合结果。','Submit records, valid count and aggregate.'],['无效/陈旧样本不混入结果，字段单位与含义清楚。','Exclude invalid/stale samples and document field meaning/units.']]});

addLesson8({id:'c-bits',area:'C逐步编程',title:['二进制、掩码与寄存器影子值','Binary, masks and shadow registers'],pre:['c-conditions','c-values'],goal:['能手算置位、清位和测试位，识别硬件寄存器例外。','Calculate setting/clearing/testing bits and identify register exceptions.'],refs:['c'],sections:[
 ['十六进制方便看位','Hex groups bits','一个十六进制位对应4个二进制位，0xA5写作1010 0101。位编号从最低位0开始。十六进制只是数值表示方式，不意味着数据一定存于硬件寄存器。','One hexadecimal digit represents four bits; 0xA5 is 1010 0101. Bit numbering starts at zero on the least-significant side. Hex is notation, not proof that a value is a hardware register.'],
 ['掩码只选择特定位','Masks select bits','1u<<3产生第3位为1的无符号掩码。x|mask置位，x&~mask清位，(x&mask)!=0测试。位运算&、|与逻辑&&、||不同，前者逐位处理，后者生成真假。','1u<<3 creates an unsigned bit-three mask. OR sets, AND with complement clears and (x&mask)!=0 tests it. Bitwise &/| differ from logical &&/||.'],
 ['移位也有合法范围','Shifts have bounds','移位次数必须小于所用提升后类型的位宽且不能为负。初学优先用无符号类型与已知范围，不把负数移位和有符号溢出当跨平台保证。固定宽度类型还要包含stdint.h并确认实现提供。','Shift counts must be nonnegative and below the promoted type width. Prefer unsigned types and known bounds. Negative/signed cases are not blanket portability guarantees; fixed-width types require stdint.h and implementation support.'],
 ['真实寄存器要看手册','Real registers have semantics','本课只修改普通变量的“寄存器影子值”。真实寄存器可能只读、写1清零、读取清标志或保留位必须维持特定值。对其读改写前必须核对语义，不能把普通变量例题直接复制。','This exercise changes ordinary shadow variables. Real registers may be read-only, write-one-to-clear, read-to-clear or have reserved-bit constraints. Check semantics before applying read-modify-write.']
 ],example:['unsigned x=0xA5u; x |= (1u<<3); 得0xAD；再x &= ~(1u<<2); 得0xA9。每一步可先写8位图再核对十六进制输出。','Starting unsigned x=0xA5u, x |= (1u<<3) gives 0xAD; then x &= ~(1u<<2) gives 0xA9. Trace the eight-bit pattern before printing hex.'],error:['逻辑且&&不能代替按位与&；寄存器读数也可能有副作用。','Logical AND cannot replace bitwise AND, and register reads may have side effects.'],answer:['置第3位得0xAD，随后清第2位得0xA9，其余位保持。','Setting bit three gives 0xAD; clearing bit two gives 0xA9, preserving the others.'],task:[['用普通变量模拟三个状态标志。','Model three status flags in an ordinary variable.'],['例题两次更新后的十六进制值是什么？','What hex values follow the two updates?'],['手画位图后运行置位、清位、测试位程序。','Draw bit patterns and run set/clear/test operations.'],['解释为什么清位不会把其他位全部清空。','Explain why clearing one bit preserves the others.'],['选择另一个起始值，重复同样掩码操作。','Repeat the masks from another initial value.'],['提交每步二进制/十六进制及输出。','Submit bit/hex traces and outputs.'],['结果与手算一致，能指出至少一种不能普通读改写的寄存器。','Match calculations and name a register behavior that forbids ordinary read-modify-write.']]});

addLesson8({id:'c-modules',area:'C逐步编程',title:['头文件、多文件构建与接口','Headers, multi-file builds and interfaces'],pre:['c-functions','c-build'],goal:['能把计算拆成接口与实现，并完整构建两个源文件。','Separate interface/implementation and build two source files together.'],refs:['c','gcc'],sections:[
 ['头文件声明，源文件实现','Declarations and implementation','calc.h声明函数原型，calc.c定义计算，main.c调用。调用者包含头文件才能按同一签名使用函数。把大段函数定义无条件放入多个编译单元包含的头文件可能产生重复定义。','calc.h declares functions, calc.c defines them and main.c calls them. Callers include the same declaration. Unconditionally placing ordinary function definitions in multiply included headers can cause duplicate definitions.'],
 ['声明要保持一致','Keep signatures consistent','参数类型、顺序和返回类型都属于接口。实现文件也包含自己的头文件，让编译器帮助发现不一致。不能只在main里临时写另一个猜测原型，让链接“侥幸”通过。','Parameter types/order and return type form the interface. The implementation includes its own header so compiler checks can catch disagreement. Do not invent a separate guessed prototype in main.'],
 ['构建必须包含实现','Build every required source','gcc main.c calc.c -o demo把两个源一起交给工具链。只编main.c时可能找不到函数定义。构建系统负责追踪依赖和命令，但入门先手工理解少量文件关系。','gcc main.c calc.c -o demo builds both sources. Omitting calc.c can leave missing definitions. Build systems later track dependencies, but first understand the small manual build.'],
 ['保护头文件与保留源文件','Guard headers and retain source','用include guard或项目认可方式避免头文件被重复展开带来的重复声明类型问题。分享工程时保留.h、.c与构建说明；只发本机可执行文件不等于提供可修改可重建项目。','Use include guards or an accepted project mechanism against problematic repeated inclusion. Share headers, sources and build instructions; a local executable alone is not an editable/rebuildable project.']
 ],example:['calc.h声明double square(double x); calc.c定义double square(double x){return x*x;}，main调用square(3.0)应得9。构建命令必须包含main.c和calc.c。','calc.h declares double square(double x); calc.c defines it as return x*x; main calls square(3.0) and expects 9. Build both main.c and calc.c.'],error:['#include一个头文件不等于自动把另一个.c文件编译链接进来。','Including a header does not automatically compile/link its implementation source.'],answer:['头文件只有声明，链接仍需要calc.c产生的定义。','The header declares; linking still needs the definition from calc.c.'],task:[['把平方函数变成可复用小模块。','Create a reusable square-function module.'],['只include calc.h，链接是否一定能找到square实现？','Does including calc.h guarantee square is linked?'],['创建三个文件，完整构建；再省略calc.c记录错误。','Create the three files, build all, then omit calc.c and record the error.'],['画调用、声明和定义之间的关系。','Draw caller/declaration/definition relationships.'],['增加另一个函数并更新同一接口与构建。','Add another function through the same interface/build.'],['提交源码目录与从空输出目录重建记录。','Submit source layout and a clean-output rebuild record.'],['接口一致、无重复定义、重建可复现。','Keep interfaces consistent, avoid duplicate definitions and reproduce the build.']]});

addLesson8({id:'c-debug',area:'C逐步编程',title:['调试：断点、单步、变量与最小复现','Debugging: breakpoints, steps, state and reproduction'],pre:['c-arrays','c-modules'],goal:['能以证据定位错误发生的第一步，而非只修改最终输出。','Locate the first wrong step with evidence instead of patching output.'],refs:['gcc','c'],sections:[
 ['先写预期，再看实际','Write expectations first','对三个样本求和，先手算每轮结果。最终总和不对时，检查第一次偏离的循环，而不是直接加减常数“校准”。输入固定、步骤最少的复现程序比包含全部硬件功能的大工程更易分析。','Hand-calculate each iteration of a three-sample sum. Locate the first divergence rather than adjusting the final result with a magic constant. A small fixed-input reproduction is easier than a full hardware project.'],
 ['调试信息与优化','Debug information and optimization','GCC使用-g生成调试信息，入门可用-O0减少优化对源码步骤的重排影响。编译器选项因工具链而异。发布优化后仍需重测，调试版本通过不代表所有构建行为完全相同。','GCC -g supplies debug information and -O0 helps keep beginner stepping close to source. Options vary by toolchain. Retest optimized releases; passing a debug build does not establish identical behavior everywhere.'],
 ['断点看状态，不只是暂停','A breakpoint reveals state','在循环前设置断点，检查初始sum和长度；单步一轮查看索引及元素。进入函数和越过函数是不同调试动作。观察变量前确认当前栈帧与作用域，避免把同名局部变量看混。','Break before the loop and inspect sum/length, then step through index and element updates. Step into versus over differ. Verify stack frame/scope when inspecting same-named locals.'],
 ['修复后加回归用例','Preserve a regression case','记录失败输入和期望，把它保留为以后每次修改后的检查。内存检查器能帮助发现部分越界，但不是所有正确性的证明。警告、单步、断言与测试互相补充。','Keep the failing input and expected result as a regression check. Memory diagnostics detect some defects but do not prove all correctness. Warnings, stepping, assertions and tests complement each other.']
 ],example:['程序在循环体内把sum重置0，输入[2,4,6]最后输出6而非12。断在第二轮前后可看到sum从2被清零；把初始化移到循环前才是修复。','Resetting sum inside the loop makes [2,4,6] output 6 instead of 12. Stepping the second iteration reveals sum reset from 2; moving initialization before the loop fixes the cause.'],error:['让最终结果恰好对上一个例子不等于修复根因。','Matching one final result does not establish a root-cause repair.'],answer:['错误发生在每轮清零，第二轮进入前的累计值被丢弃。','Each reset discards accumulated work; the second iteration reveals the loss.'],task:[['调试一个故意放错初始化位置的求和程序。','Debug a deliberately misplaced accumulator initialization.'],['为什么[2,4,6]最后只剩6？','Why does [2,4,6] finish as six?'],['保存最小失败例，用打印或已安装调试器追踪每轮值。','Preserve a minimal failure and trace iterations with prints or an installed debugger.'],['指出第一处偏离及对应源码行。','Identify the first divergence and source line.'],['修复后测试[1]、[-2,2]和原失败输入。','After repair test [1], [-2,2] and the original failure.'],['提交失败轨迹、最小修复与回归表。','Submit failure trace, minimal repair and regression table.'],['解释根因且三组回归通过，不靠修正最终常数。','Explain the cause and pass three regressions without output-offset patches.']]});

addLesson8({id:'c-state',area:'C逐步编程',title:['状态机、时间戳与非阻塞任务','State machines, timestamps and nonblocking tasks'],pre:['c-conditions','c-loops','c-structs'],goal:['能用明确状态处理按钮/超时，并保持其他任务可运行。','Use explicit states for events/timeouts while other work continues.'],refs:['c'],sections:[
 ['状态描述现在处于哪一步','State describes the current phase','用枚举表达IDLE、WAIT、ACTIVE，比多个可能矛盾的布尔标志更清楚。每个事件只在规定状态触发转换，进入和退出动作写清楚。状态名不是注释，要参与程序判断。','An enum such as IDLE, WAIT and ACTIVE is clearer than conflicting booleans. Define event-driven transitions and entry/exit actions. State labels must participate in logic, not merely comments.'],
 ['时间差代替长时间停住','Elapsed time instead of blocking','记录进入WAIT的时间start，每次循环检查now-start是否达到期限，未达到就返回主循环做别的工作。不要用长延时阻塞通信和停止请求；时间来源与溢出策略需要单独约定。','Record WAIT entry time and check elapsed time on each iteration, returning to other work while waiting. Long delays block communication and stop requests. Define time source and rollover handling explicitly.'],
 ['输入事件要有定义','Define events precisely','按钮按下、电平保持、释放是不同事件。机械消抖可要求输入持续稳定一段时间再接受状态变化。消抖时间需结合设备，不把课堂20ms当所有按键的通用标准。','Press edge, held level and release are different events. Debouncing can require a stable interval before accepting a change. Choose timing for the device; a classroom 20 ms is not universal.'],
 ['用事件表代替等实物','Test with event sequences','先给状态机一串合成时间与事件，记录每步状态和输出。包括正常按压、快速抖动、取消和超时。把硬件读引脚封装为输入，让状态逻辑能在电脑单独测试。','Feed synthetic timestamped events and record states/outputs for normal operation, bounce, cancel and timeout. Separate pin reading from state logic so it can be tested on a computer.']
 ],example:['课堂规则：首次按下进入WAIT；持续稳定20ms后ACTIVE；期间释放则回IDLE。t=0按下、t=10释放不会激活；t=100按下且保持到120才激活。','Classroom rule: press enters WAIT, stable 20 ms enters ACTIVE, early release returns IDLE. Press at 0/release at 10 does not activate; press at 100 held until 120 does.'],error:['一条delay(20)可能阻塞其他工作；状态机也必须测试意外事件和超时。','A delay can block unrelated work; state machines still need unexpected-event and timeout tests.'],answer:['首次按压未保持满20ms应取消；第二次保持到120ms才激活。','The first press cancels before 20 ms; the second activates at 120 ms.'],task:[['用合成事件实现可取消的等待动作。','Implement a cancellable wait using synthetic events.'],['示例中的两次按压哪次会激活？','Which sample press activates?'],['实现状态转移，逐条送入示例时间和事件。','Implement transitions and feed the example timestamps/events.'],['说明等待期间主循环还能处理哪些工作。','Explain work the main loop can perform while waiting.'],['新增STOP事件，使任何状态都回到明确定义的安全输出。','Add STOP to reach a defined safe output from every state.'],['提交转移表、事件轨迹和输出。','Submit transition table, event trace and outputs.'],['正常/取消/停止各路径通过，没有不可退出状态。','Pass normal/cancel/stop paths without an inescapable state.']]});

addLesson8({id:'breadboard-nodes',area:'实物制作基础',title:['面包板：孔、金属夹与电气节点','Breadboards: holes, clips and electrical nodes'],pre:['start','kirchhoff','meter'],lab:'breadboard',goal:['能先画内部连接，再用断电通断检查验证面包板节点。','Map internal connections and verify breadboard nodes with unpowered continuity checks.'],refs:['board'],sections:[
 ['孔下面有金属连接','Metal connects groups of holes','常见面包板中部每侧一组5孔由金属夹相连，中央沟槽把左右两组隔开；孔排列相邻不代表同一节点。实际板型可能不同，应先读结构示意，再用断电通断档确认。','Many breadboards connect five-hole groups on each side of a center gap. Adjacent-looking holes need not share a node. Designs vary; inspect the actual layout and confirm with unpowered continuity checks.'],
 ['节点由导线连通决定','Connectivity defines a node','把同一金属夹上的孔视为同一节点。如果电阻两脚插进同一组孔，两脚被金属短接，电阻不再承担预期压降。摆放角度和颜色不能改变内部连接。','Holes on one clip share a node. Both resistor leads in the same connected group are shorted by the clip and cannot create the intended voltage drop. Appearance and orientation do not override connectivity.'],
 ['中央沟槽服务双排器件','The center gap separates package rows','双排直插器件通常跨中央沟槽，两侧引脚分别进入不同连通组。必须先核对1脚方向和引脚图。把双排器件同侧错插可能把原本不同引脚接到一起，不能只看“插得进去”。','DIP packages commonly bridge the center gap so opposite pin rows remain separated. Verify pin one and pinout. A mechanically fitting placement can still short pins that should be separate.'],
 ['在无电空板上建立地图','Map an unpowered board','拔掉所有电源和器件，用通断档测试同组、相邻组、沟槽两侧各两孔。先短接表笔确认仪表，再记录有声/无声或电阻值。蜂鸣阈值依仪表，不把所有低阻都当理想零欧。','Remove sources/components and test same group, neighboring groups and across the gap. Verify the meter by touching probes first. Record continuity/resistance; beeper thresholds differ and low resistance is not mathematically zero.']
 ],example:['在一种标准5孔分组板上，a10到e10连通，a10到a11不连通，e10到f10跨沟槽不连通。这只是该布局的例题，真实板必须测。','On one standard five-hole layout, a10–e10 connect, a10–a11 do not and e10–f10 cross an isolated gap. Verify the actual board rather than universalizing these labels.'],error:['面包板每一整行十孔不一定全通，中央沟槽通常隔开两边。','A ten-hole visual row is not necessarily one node; the center gap commonly isolates halves.'],answer:['同一连通组把电阻两端短接，电阻不能作为两个节点之间的限流元件。','One connected group shorts the resistor terminals, removing its intended between-node limiting role.'],task:[['为一块空面包板制作连接地图。','Map an empty breadboard.'],['电阻两脚插同一连通组会怎样？','What happens when both resistor leads share one connected group?'],['断电检查三类孔对，把连通组涂成相同颜色；无实物时在模型中完成并标模拟。','Test three pair types unpowered and color connected groups; without hardware use the model and label it simulated.'],['用节点解释结果，不用“左右看起来相邻”。','Explain using nodes rather than visual proximity.'],['换一组未测孔，先预测再测。','Predict and test an unmeasured group.'],['提交连接图和至少6个孔对记录。','Submit a map and at least six pair checks.'],['图与检查一致，能识别同组短接和中央隔离。','Match the map to checks and identify same-group shorts and central isolation.']]});

addLesson8({id:'breadboard-led',area:'实物制作基础',title:['把LED原理图搬到面包板','Translate an LED schematic to a breadboard'],pre:['breadboard-nodes','components','wiring-guide','power'],lab:'breadboard',goal:['能用连接表搭建一条有限流的低压LED回路。','Build a current-limited low-voltage LED loop from a connection list.'],refs:['board'],sections:[
 ['先给原理图节点命名','Name schematic nodes first','把回路分为电源正端N1、电阻与LED之间N2、回流端N0。电阻跨N1/N2，LED阳极接N2、阴极接N0。先写这张连接表，再决定具体插孔；位置改变不应改变节点关系。','Name source positive N1, resistor/LED junction N2 and return N0. The resistor spans N1/N2; LED anode goes to N2 and cathode N0. Choose holes only after defining this netlist.'],
 ['极性与阻值分开确认','Check polarity and resistance separately','电阻一般无方向，LED有极性；脚长和壳体标记可辅助，但准确型号资料与测量更可靠。预先读阻值，检查两脚确实处在不同节点。LED串联电阻放前或后均可限流，只要仍在同一串联路径。','A resistor is normally nonpolar; an LED is polar. Leads/markings help but verify the part. Check resistance and distinct nodes. A series resistor can precede or follow the LED if it remains in the same series branch.'],
 ['先断电检查，再限流上电','Inspect unpowered, then limit power','电源关闭时逐节点检查连线、极性、供电轨是否短接。第一次使用已确认的低压、限流电源，并按元件额定值设置。真实LED不亮先断电排查，不能盲目提高电压。','With output off, inspect connections, polarity and supply shorts. Use a verified low-voltage current-limited supply within component ratings. If dark, switch off and diagnose instead of blindly raising voltage.'],
 ['用压降定位断点','Diagnose using node voltages','正常情况下电源电压约等于电阻压降与LED压降之和。测量时标明红黑笔位置；若某节点意外等于电源或0V，应结合连通关系判断开路、短路或极性，而不是只靠亮度。','In normal operation, source voltage approximately equals resistor plus LED drops. Record probe locations; unexpected rail-level nodes require connectivity-based diagnosis of opens, shorts or polarity, not brightness alone.']
 ],example:['教学模型5V、LED2V、330Ω：N1对N0为5V，N2对N0约2V，电阻两端约3V，电流9.09mA。真实数值随LED和电源误差变化。','Teaching values 5 V, 2 V LED and 330 Ω give N1=5 V, N2≈2 V, resistor≈3 V and 9.09 mA. Real values depend on LED/source variation.'],error:['LED已经很亮不代表电流在额定范围内；亮度不能替代计算和测量。','Brightness does not establish rated current; calculate and measure.'],answer:['只要电阻仍与LED串联在同一路径，前后顺序不改变同一支路电流。','A resistor before or after the LED has the same branch current when it remains in series.'],task:[['按节点表复现LED回路。','Reproduce an LED circuit from its node table.'],['把电阻从LED前换到后面还能限流吗？','Does moving the series resistor after the LED still limit current?'],['先画节点，再在模型或断电实板布线，记录检查后才启用低压限流。','Draw nodes, wire the model or unpowered board and inspect before low-voltage limited power.'],['用三处压降说明电压分配。','Explain voltage distribution using three measurements.'],['换一组插孔保留相同节点，再验证结果。','Move to different holes while preserving nodes and verify again.'],['提交节点表、布线图和预测/读数；区分模拟与实测。','Submit netlist, layout and predicted/read values labeled simulated or measured.'],['串联限流存在、极性正确、三处读数与模型误差解释一致。','Preserve limiting/polarity and explain readings against the model.']]});

addLesson8({id:'breadboard-power',area:'实物制作基础',title:['分断电源轨、共地与多电压分区','Split power rails, shared reference and voltage zones'],pre:['breadboard-led'],lab:'breadboard',goal:['能发现分断轨和遗漏回流，避免连接不同电源输出。','Detect split rails/missing returns and avoid tying different supply outputs together.'],refs:['board'],sections:[
 ['红蓝线是标识不是导线','Colored lines are labels','电源轨旁的红蓝标记提示用途，但不会自动连接电源。部分长轨中间断开，上下两条同色轨也可能互不相连。只凭同色判定通电会导致半块板没电。','Red/blue markings suggest intended use but do not supply voltage. Some long rails split midway and same-colored rails can be separate. Color alone cannot establish electrical continuity.'],
 ['按节点需求决定跳线','Bridge only the intended node','确认两段都应是同一电压节点后，才用跳线连接并断电检查。如果一段规划5V、另一段3.3V，就必须保持隔离并明确标注。不能为了“全板有电”把所有红轨连在一起。','Bridge segments only after confirming they should be the same voltage node. Keep planned 5 V and 3.3 V zones separate and labeled. Do not join every red rail merely to power the whole board.'],
 ['信号需要参考与回路','Signals need reference and return','非隔离数字信号通常需要兼容电平与共同参考地，但共地不等于并联两个稳压输出。两个电源正端能否连接取决于设计；电机大电流回流也不宜任意穿过敏感传感器参考路径。','Nonisolated digital signals generally need compatible levels and a shared reference, but sharing ground does not authorize paralleling regulator outputs. Large motor returns also affect sensitive references.'],
 ['量轨电压时说清测点','Name rail measurement points','上电后对每个分区分别测正轨相对本区参考轨的电压，并标注测点。某段0V可能是缺少供电或参考，不能只根据跨区读数推断。发现异常先关闭输出再检查跳线。','Measure each zone relative to its defined reference and label probes. A zero reading may reflect missing supply or reference. Diagnose the topology and switch off before changing jumpers.']
 ],example:['同一红轨中间断开，左半接5V，右半未接。给右半LED接线时不亮；断电确认断点后，只有右半也规划5V才桥接左右红轨。','A split red rail has 5 V on the left and no feed on the right. A right-side LED stays dark. Bridge only after unpowered testing and confirming both halves are intended as 5 V.'],error:['共地与共电源不是同义词，3.3V和5V输出不能因颜色相同就并接。','Shared ground is not shared positive supply; same color does not justify joining 3.3 V and 5 V outputs.'],answer:['要测内部连通与两段电压，颜色连续不代表金属连接连续。','Check actual continuity and segment voltages; continuous color does not prove continuous metal.'],task:[['查出一条“看起来有电但不亮”的分断轨故障。','Diagnose a seemingly powered but dark circuit on a split rail.'],['一条连续红线能证明两端连通吗？','Does a continuous red marking prove electrical continuity?'],['建立轨段地图，断电查分断点，再按同电压节点需求连接。','Map segments, find splits unpowered and bridge only intended equal-voltage nodes.'],['解释为何并地不等于并两个正输出。','Explain shared reference versus paralleled positive outputs.'],['纸面设计5V与3.3V两个分区及信号参考。','Design separate 5 V/3.3 V zones and signal reference on paper.'],['提交轨段表、跳线理由及测点图。','Submit segment table, jumper rationale and measurement map.'],['所有桥接有节点依据，不把不同电压正端相连。','Justify every bridge by node intent and keep different positive rails separate.']]});

addLesson8({id:'perfboard-layout',area:'实物制作基础',title:['洞洞板：从节点表到点对点布局','Perfboard: netlists to point-to-point layout'],pre:['breadboard-power','solder'],lab:'perfboard',goal:['能区分独立焊盘与条形铜板，并规划不混淆正反面的连线。','Distinguish isolated pads/stripboard and plan wiring without mirror confusion.'],refs:['solder','board'],sections:[
 ['洞洞板不等于面包板','Perfboard is not a breadboard','独立焊盘洞洞板通常每孔铜环互不相连，必须用引脚、导线或明确焊桥连接。条形板则预先有连续铜条，可能需要切断。先观察铜面并断电测通断，不能套用面包板5孔规则。','Isolated-pad perfboard usually requires wires/leads or intentional bridges between pads. Stripboard has continuous strips that may need cuts. Inspect and test; breadboard five-hole grouping does not apply.'],
 ['元件面和焊接面是镜像','The underside is mirrored','从元件面画坐标后，翻到铜面左右可能反转。标记板角、连接器1脚和基准方向，制作对应图。极性元件和IC的脚位尤其不能靠翻转后的视觉猜测。','The solder side can appear mirrored relative to the component side. Mark a reference corner, orientation and connector pin one and draw both views. Never guess polarized/IC pins from a flipped appearance.'],
 ['先布局再剪线','Plan before cutting','先放连接器、较大器件和固定孔，再规划电源、回流与信号。导线只剥需要的长度，交叉处保持绝缘；线的颜色表达用途但不能替代网络标签。留出表笔可触及的测试点。','Place connectors, large parts and mounting needs first, then route supply, return and signal. Strip only needed length, insulate crossings and label nets rather than relying only on colors. Leave accessible test points.'],
 ['连接清单驱动检查','A connection list drives inspection','为每条网络列出必须相连的端点，并另列必须不通的网络对。布局图只是计划，焊后要按清单实测。改动时更新图和版本，避免“板已经改了、图还是旧的”。','List required connected endpoints and pairs that must remain isolated. Layout is a plan; verify after assembly. Update drawings/version when wiring changes so documentation matches the board.']
 ],example:['N1连接电源正端与电阻一脚；N2连接电阻另一脚与LED阳极；N0连接LED阴极与电源负端。独立铜环不会替你完成这三条网络，需逐条布线。','N1 connects supply positive/resistor; N2 connects resistor/LED anode; N0 connects cathode/return. Isolated pads do not create these nets automatically; wire each explicitly.'],error:['两孔距离近或焊锡颜色相同不代表它们可靠相连。','Nearby pads or similar-looking solder do not establish a reliable connection.'],answer:['必须根据板型检查铜层；独立焊盘需要人为连接，不能假定内部已有五孔金属夹。','Inspect the copper pattern; isolated pads require intentional connections rather than assumed five-hole clips.'],task:[['把已有LED节点表迁移到洞洞板布局。','Transfer the LED netlist to perfboard.'],['相邻两个独立焊盘默认连通吗？','Are adjacent isolated pads connected by default?'],['画元件面与焊接面，标基准角和三条网络，再用模型检查。','Draw both board views with reference corner/nets and inspect in the model.'],['说明翻面后如何确认同一引脚。','Explain identifying the same pin after flipping.'],['把连接器换到另一边，重新规划但保持网络不变。','Move the connector and reroute while preserving the netlist.'],['提交双面布局、连接表与隔离表。','Submit both layouts, connectivity list and isolation list.'],['正反对应正确，每条导线有明确端点且交叉绝缘。','Match both views and define endpoints/insulated crossings.']]});

addLesson8({id:'perfboard-solder',area:'实物制作基础',title:['点对点焊接、机械固定与逐点验收','Point-to-point soldering and inspection'],pre:['perfboard-layout','solder','meter'],lab:'perfboard',goal:['能按连接表安排焊接顺序，区分润湿、机械固定与电气通过。','Plan soldering from a netlist and distinguish wetting, strain relief and electrical checks.'],refs:['solder'],sections:[
 ['接头需要同时受热','Heat the intended joint','连接可靠依赖焊料对焊盘和引脚的润湿。只把一团熔锡滴上去，可能外观连着但界面未充分结合。烙铁头清洁、接触面积和热容量共同影响传热，温度设定不是焊点实测温度。','A reliable joint needs wetting of pad and lead. Dropping molten solder can look connected without a sound interface. Tip cleanliness, contact and thermal mass affect heat transfer; setpoint is not measured joint temperature.'],
 ['分步焊，分步查','Assemble and inspect incrementally','先固定较低器件，再处理接线与连接器，每完成一条网络就冷却后检查。避开一次焊完全部才寻找错误。剪脚注意收集碎屑，供电始终断开，工作区具备合适通风和热工具支架。','Secure low parts first, then wiring/connectors, inspecting after each net cools. Avoid waiting until the whole board is finished. Collect cut leads, keep power removed and use ventilation and a safe iron stand.'],
 ['导线拉力不能靠焊盘承担','Provide strain relief','连接器插拔和导线拉动会把力传给焊点。用机械固定或应力释放减小反复弯折，绝缘套保护裸露连接。胶和扎带不能修复本来未润湿的坏接头，也不能遮住尚未验收的短路。','Cable/connector loads stress joints. Provide mechanical strain relief and insulation. Adhesive or ties cannot repair poor wetting or justify covering a joint before short-circuit inspection.'],
 ['外观与电气分开记录','Separate visual and electrical evidence','检查焊料分布、桥连、毛刺、松动及热损伤，再做断电网络通断和相邻网络隔离。外观光亮不是唯一标准；某次蜂鸣也不能证明长期抗振可靠。首次上电仍要限流。','Inspect wetting/shape, bridges, whiskers, looseness and damage, then verify unpowered continuity/isolation. Shine alone is insufficient, and one beep does not establish vibration reliability. Initial energization remains current-limited.']
 ],example:['计划N2只连电阻和LED阳极，焊后却连到N0：这是不期望桥连。先断电修复并重新做N2→N0隔离检查，再考虑上电，而不是用程序“补偿”。','If N2 should join only resistor/LED anode but also connects to N0, an unintended bridge exists. Repair unpowered and repeat isolation checks before energizing; software cannot compensate for this wiring defect.'],error:['焊点越大不一定越牢，覆盖焊盘周围可能掩盖桥连和未润湿。','More solder is not necessarily stronger and can hide bridging or poor wetting.'],answer:['先修复不期望连接并复查隔离；限流电源不是允许带短路继续使用的理由。','Repair the unintended connection and recheck isolation; current limiting does not authorize using a shorted assembly.'],task:[['为三网络小板设计分步焊接与验收流程。','Plan staged soldering/inspection of a three-net board.'],['N2意外连到N0，应先做什么？','What comes first when N2 unexpectedly joins N0?'],['在模型标出焊接点、检查点与桥连；有合适工具时按分步流程制作练习板。','Mark joints/checkpoints/bridge in the model; with suitable tools, assemble incrementally.'],['区分外观、通断和机械固定三类证据。','Distinguish visual, electrical and mechanical evidence.'],['加入一根外接线并设计应力释放。','Add an external lead and plan strain relief.'],['提交每网络检查记录，模拟或实物明确标注。','Submit per-net checks labeled simulated or physical.'],['预期网络通、非预期网络隔离，裸线受保护且不会被拉力直接牵动焊盘。','Verify intended continuity/isolation and protected, strain-relieved leads.']]});

addLesson8({id:'modules-levels',area:'实物制作基础',title:['转接模块：连接器、电源和信号电平','Adapter modules: connector, supply and logic level'],pre:['breadboard-power','protocol'],lab:'breadboard',goal:['能逐引脚核对模块接口，不把接口形状或供电电压当信号兼容证据。','Verify module pin contracts rather than trusting connector shape or supply voltage.'],refs:['board'],sections:[
 ['先看模块实际做了什么','Identify the module function','USB转串口、降压模块、双向电平转换板和传感器分线板用途不同。外形相似不表示互换。查准确板号、原理图、芯片和每个引脚功能，区分只是引出引脚还是进行了电平/电源转换。','USB-UART, regulators, level shifters and breakouts perform different functions. Similar form does not imply interchangeability. Identify board/chip/pinout and whether it merely exposes pins or actually translates voltage.'],
 ['供电入口不决定信号电平','Supply input does not define logic','一个模块可接受5V供电，却输出3.3V逻辑；另一个5V输入脚可能直接连芯片供电。GPIO是否5V容忍须查准确器件及模式，不能用“以前插过没坏”作为规格。','A module may accept 5 V power yet use 3.3 V logic; another pin may directly feed a chip. Verify exact GPIO tolerance/mode, not anecdotal survival.'],
 ['逐根定义方向与参考','Define direction and reference','UART常见TX接对方RX、RX接对方TX，并建立适当共同参考；但RS-232电气接口不能直接当TTL UART。I²C开漏总线的转换方式也不等于推挽SPI的通用转换。','UART commonly crosses TX/RX and needs an appropriate reference, but RS-232 electrical levels are not TTL UART. An I²C open-drain translator is not automatically suitable for push-pull SPI.'],
 ['做接口表后才接线','Write an interface table','表格逐行列源引脚、方向、逻辑高低范围、允许输入、目标引脚和参考地。若任何一项未知，先查文档而不是试插。模块带稳压器也不意味着它能为电机或外部系统供足电流。','List source pin, direction, logic range, allowed input, destination and reference for each connection. Resolve unknowns before plugging in. An onboard regulator does not guarantee adequate motor/system power.']
 ],example:['假定A的TX最高3.3V，B的RX要求高电平至少2.0V且允许到3.6V，静态电平条件可满足；仍需共同参考、速率和引脚功能核对。相反5V TX超过3.6V上限不能直接接。','Assume TX high is 3.3 V and RX needs at least 2.0 V while allowing up to 3.6 V: static levels can fit, but reference/timing/pin function still matter. A 5 V TX exceeds that limit.'],error:['“5V模块”这个标签没有说明每个GPIO的允许电压。','A “5 V module” label does not specify every GPIO’s allowed voltage.'],answer:['先比较发送高电平与接收阈值和绝对输入限制，不能只看模块供电。','Compare transmitter levels, receiver thresholds and input limits, not only supply labels.'],task:[['给两个假设串口模块制作接口匹配表。','Prepare an interface match table for two hypothetical UART modules.'],['5V供电能证明其TX一定是5V吗？','Does 5 V supply prove TX is 5 V?'],['按例题填引脚、电平、方向、参考与速率；标出未知项。','Fill pins, levels, direction, reference and speed; mark unknowns.'],['解释为什么USB转串口和RS-232转换器不能按名字互换。','Explain why USB-UART and RS-232 adapters are not interchangeable by name.'],['把一个接收上限改3.0V，重新判断。','Change the receiver limit to 3.0 V and reassess.'],['提交接口表和每个判断的规格来源。','Submit the interface table and specification source for each decision.'],['所有连接有依据，超限与未知均被识别。','Justify each connection and identify limits/unknowns.']]});

addLesson8({id:'modules-power',area:'实物制作基础',title:['电源模块：输入、输出、负载与首次上电','Power modules: input, output, load and first power-up'],pre:['modules-levels','power','protection'],lab:'breadboard',goal:['能绘制供电树、核对调压与功率，并安排限流上电。','Draw a power tree, check regulation/power and plan limited first energization.'],refs:['board'],sections:[
 ['输入输出不能接反','Separate input and output','降压模块的VIN/GND与VOUT/GND承担不同角色。端子位置和丝印可能随板型变化，先查准确资料；不能以电位器在左就猜输入在左。输入也需满足启动、最大值和极性条件。','VIN/GND and VOUT/GND have distinct roles. Terminal layout varies, so inspect exact documentation rather than guessing from trimmer position. Verify input startup/range/polarity.'],
 ['先设定再接敏感负载','Set before attaching sensitive loads','可调输出模块先按厂家允许的测试方式确认输出，再断电接目标负载。调节范围可能远高于目标板耐压。空载电压正确只是一步，负载变化时的跌落、纹波和启动过冲还要另外评估。','Confirm adjustable output using the manufacturer’s allowed test conditions before attaching a sensitive load. Range may exceed the board limit. No-load voltage alone does not establish loaded regulation, ripple or startup behavior.'],
 ['功率与热不是标牌数字','Budget power and heat','理想降压近似输入功率等于输出功率，真实还有损耗。5V×0.5A=2.5W输出，效率85%时输入约2.94W。标称最大电流受散热、输入差和环境影响，不应默认可长期满额。','A 5 V, 0.5 A output is 2.5 W; at 85% efficiency input is about 2.94 W. Ratings depend on cooling, input conditions and environment, not merely the printed maximum current.'],
 ['用供电树防止回灌','A power tree reveals backfeeding','把USB、外部电源、稳压模块和负载画成供电树，标是否允许同时接入、隔离二极管或电源选择。两个输出直接相接可能回灌；先按板卡电源设计确定来源，不凭“电压一样”就并联。','Draw USB, external supply, regulators and loads, including allowed simultaneous sources and selection/isolation. Equal nominal voltages do not authorize paralleling outputs; one may backfeed another.']
 ],example:['输出5V/0.5A、假定效率85%，Pout=2.5W，Pin≈2.94W，损耗约0.44W。这不包含某次启动峰值，仍需根据实际负载与模块测试。','At 5 V/0.5 A and assumed 85% efficiency, output is 2.5 W, input about 2.94 W and loss about 0.44 W. Startup peaks still require actual load/module checks.'],error:['“能调到3.3V”不等于能在目标负载、温度和启动条件下稳定供电。','Reaching 3.3 V does not establish regulation under load, temperature or startup.'],answer:['先确认模块输出与极性，再连接敏感负载；不要边盲调边用目标板承受测试。','Verify output/polarity first rather than using the sensitive board as a blind adjustment load.'],task:[['为控制板和传感器设计供电树。','Design a controller/sensor power tree.'],['可调模块未知输出时应先接目标板试吗？','Should an unknown adjustable output be tried on the target board first?'],['列各负载电压/电流，画供电树并算功率预算。','List load voltages/currents, draw the tree and calculate power.'],['解释USB与外部供电是否允许同时使用及依据。','Explain simultaneous USB/external supply permission and its source.'],['把一个负载电流翻倍，重算输入与损耗。','Double one load current and recompute input/loss.'],['提交预算、上电顺序和未知项清单。','Submit budget, startup sequence and unresolved items.'],['输入输出清楚，不超额、不盲并电源，未知条件未被当作已满足。','Clarify input/output, limits and source isolation without assuming unknowns are satisfied.']]});

addLesson8({id:'hardware-check',area:'实物制作基础',title:['断电检测、分段上电与故障记录','Unpowered checks, staged power-up and fault records'],pre:['perfboard-solder','modules-power'],lab:'perfboard',goal:['能按节点、极性、隔离和分段上电制定可执行检查流程。','Define executable checks for nodes, polarity, isolation and staged power-up.'],refs:['solder','board'],sections:[
 ['断电必须包括所有来源','Remove every energy source','关闭一个开关未必移除了USB、电池或外部模块反向供电。确认所有来源与储能已按设备要求处理，才能用电阻/通断档。检查前确认表笔、插孔和功能，不能拿电流档去找短路。','One switch may leave USB, batteries or backfeeding sources active. Verify all sources/stored energy before resistance/continuity checks. Confirm meter leads, jack and function; current mode is not a short-finding substitute.'],
 ['通和不通都要验收','Verify connection and separation','按网络表检查应相连端点，再检查相邻电源轨与不同信号网络之间不应有的连通。读数可能受电容充电、二极管和并联路径影响，不是一次蜂鸣就能断言某芯片短路。','Check intended endpoints and unintended connections between rails/signals. Capacitors, diodes and parallel paths affect readings, so one beep does not establish a shorted chip.'],
 ['分段上电缩小搜索范围','Stage power to localize faults','先检查电源模块，再连接控制板，再加一个外设；每步记录电压、电流和异常。限流值由预期正常电流与器件限制决定，过低会使正常启动失败，过高又降低保护作用。','Verify supply first, then controller, then one peripheral at a time. Record voltage/current/anomalies. Set current limit against expected startup and ratings; too low can block normal startup and too high weakens protection.'],
 ['故障记录要能复现','Make fault records reproducible','记录硬件版本、连接图、上电条件、症状、测点和每次只改的一项。修复后重跑原失败条件及邻近正常条件。不要只记“换线好了”，还要说明断点在哪、怎样确认。','Record hardware revision, wiring, power conditions, symptoms, probes and one change per trial. Retest the failing and nearby normal conditions. “Changed a wire” is incomplete without locating and verifying the defect.']
 ],example:['控制板单独正常，加传感器后电源进入CC。先断电移除新增支路，核对其极性、阻值和电压要求；这比一次更换全部模块更能隔离原因。','A controller works alone but reaches CC after a sensor is added. Power down and isolate that branch, checking polarity/resistance/voltage requirements instead of replacing everything at once.'],error:['无烟、无发热或指示灯亮都不是完整上电验收。','No smoke, low warmth or a lit indicator is not complete power-up acceptance.'],answer:['先停止并隔离最后加入的支路，保留条件和测量；不要继续提高限流盲试。','Stop and isolate the newly added branch while preserving conditions/measurements; do not blindly raise the limit.'],task:[['验收一块三网络练习板与一个假设传感器模块。','Accept a three-net board plus a hypothetical sensor module.'],['新增模块后进入CC，下一步应扩大供电还是隔离新增支路？','After a new module causes CC, raise power or isolate the added branch?'],['完成断电网络表、隔离表与分段上电计划；有实物按条件执行。','Complete connectivity/isolation tables and staged-power plan; execute only with suitable hardware conditions.'],['解释一个读数可能受并联元件影响的例子。','Explain one reading affected by parallel components.'],['注入一个模型断路，按相同检查流程定位。','Inject a modeled open and locate it with the same procedure.'],['提交签明模拟/实物的检查表、故障与修复证据。','Submit checks labeled simulated/physical and failure/repair evidence.'],['所有来源明确、检查顺序正确、故障定位有测点依据。','Identify sources, use the correct sequence and support diagnosis with probe locations.']]});

addLesson8({id:'drone-architecture',area:'无人机台架',title:['四旋翼部件如何组成系统','How a quadrotor system fits together'],pre:['hardware-check','motor-control','protocol'],lab:'drone',level:'Intermediate',goal:['能把机架、动力、电源、飞控、传感与链路画成接口图。','Map frame, propulsion, power, flight controller, sensors and links.'],refs:['px4'],sections:[
 ['先拆成功能而不是购买清单','Begin with functions','机架提供几何与安装，电机/桨产生推力，ESC驱动电机，飞控读取传感器并输出控制，电源系统分配能量，接收/遥测链路传送命令与状态。每件都需要明确输入输出，装齐外壳不等于系统成立。','The frame sets geometry, motors/propellers create thrust, ESCs drive motors, the controller uses sensors, power distribution supplies energy and links carry commands/status. Every component needs explicit interfaces; physical presence is insufficient.'],
 ['动力路径与信号路径分开画','Separate energy and commands','电池到ESC是较大电流的动力路径，飞控到ESC是指令路径。把两类线混淆会造成接错或噪声问题。逻辑地、供电地、屏蔽与隔离按准确设备设计处理，不凭颜色统一连接。','Battery-to-ESC wiring carries propulsion current, while controller-to-ESC wiring carries commands. Confusing them creates faults/noise. Handle reference, return, shielding and isolation according to exact hardware, not colors alone.'],
 ['飞控方向属于坐标定义','Controller orientation defines a frame','飞控板的箭头、机体前方和软件设置必须一致。板旋转安装并非一定错误，但要配置真实安装旋转并验证姿态显示。传感器轴错配会让控制器把正确动作理解成另一方向。','Board arrow, body front and software orientation must agree. A rotated installation can be valid if configured and verified. Axis mismatch makes real motion appear in the wrong direction to control.'],
 ['装配验收从无桨开始','Begin acceptance without propellers','本学习台先完成模块识别、固定、接口和方向检查，电机测试始终拆桨。网页流程只说明装配依赖，不计算真实气动、推力或飞行稳定性，也不会证明任何实体飞行器可以起飞。','Identify/mount modules and check interfaces/orientation without propellers. The webpage models workflow dependencies, not aerodynamics, thrust or flight stability, and cannot clear a real aircraft for flight.']
 ],example:['若电源、飞控和四个ESC/电机均装上，但遥控器未连接、飞控前向未确认，仍缺少命令来源和坐标验收。应在接口图标未知，不能直接进入起飞尝试。','Installed power/controller/motors still lack verified command source and coordinates if the receiver/orientation are unchecked. Mark those unknowns in the interface map instead of attempting takeoff.'],error:['飞控、ESC和电机是三个不同职责的部件，不能用一个“控制板”概括全部兼容性。','Controller, ESC and motor have distinct roles; “control board” does not resolve compatibility.'],answer:['ESC把指令转为电机功率开关，飞控根据状态计算指令；两者职责不同。','The ESC switches motor power from commands; the flight controller calculates commands from state.'],task:[['完成一个四旋翼无桨系统的装配接口图。','Map a propeller-free quadrotor assembly.'],['飞控能直接用GPIO给无刷电机供电吗？','Can a flight-controller GPIO directly power a brushless motor?'],['在模块模型逐件装配，标动力/信号路径，并完成前向检查。','Assemble model modules, label power/signal paths and check orientation.'],['解释一个缺模块或方向未确认为何阻止下一步。','Explain why a missing module/orientation check blocks the next step.'],['换一种连接器布局，保持功能和坐标契约不变。','Change connector placement while retaining interface/frame contracts.'],['提交部件图、接口表和未验证项。','Submit component map, interface table and unverified items.'],['职责与方向清楚；只称无桨流程通过，不称飞行通过。','Clarify roles/direction and claim only propeller-free workflow completion.']]});

addLesson8({id:'drone-sizing',area:'无人机台架',title:['无人机选型：重量、推力与电气余量','Drone selection: mass, thrust and electrical headroom'],pre:['drone-architecture','modules-power'],lab:'drone',level:'Intermediate',goal:['能从任务和质量预算反推候选部件，并识别缺少测试表时的未知。','Use task/mass budgets to evaluate parts and identify missing test evidence.'],refs:['px4'],sections:[
 ['任务先变成预算','Translate the task into budgets','先定义载荷、续航目标、使用环境与体积，再列机架、电池、动力、飞控、线束和余量的质量。漏算线束、固定件和防护会低估起飞质量；质量变化会影响推力和续航，不能独立选每个部件。','Define payload, endurance, environment and size, then budget frame, battery, propulsion, controller, wiring and margin. Fasteners/wires matter. Mass changes affect thrust/endurance, so parts cannot be selected independently.'],
 ['悬停推力由重量决定','Hover thrust balances weight','理想静态水平悬停时总推力约mg。四个电机均分只是对称理想估算；还需控制余量、密度、安装干扰和实际推力表。推力比例不等于油门百分比，电机KV也不是直接推力参数。','Ideal level hover needs total thrust about mg. Equal division among four motors assumes symmetry. Use actual test tables and margins for control/density/interference. Thrust fraction is not throttle percentage, and KV is not a thrust rating.'],
 ['电机桨电压必须成组合','Motor, propeller and voltage are a set','比较厂家在准确电压、桨尺寸和电机型号下的推力、电流和效率表。大桨可能超出机架间距或电机负荷。ESC连续/峰值电流、散热和协议也要匹配，不能只选更大的标称数字。','Use manufacturer thrust/current data for the exact motor, propeller and voltage. A larger prop can exceed clearance or motor load. Match ESC continuous/peak current, cooling and protocol rather than chasing a larger number.'],
 ['电池与线束看整个负载','Budget the whole electrical load','汇总各电机和其他负载电流，再检查电池、连接器、导线、分电板和保险保护的能力。电池C倍率乘容量只是标称电流线索，不能替代温升、压降、状态与可靠数据；充电使用匹配电池化学体系的设备。','Sum motors and auxiliary loads, then check battery, connectors, wiring and distribution. C-rating times capacity is a nominal clue, not a substitute for thermal/voltage/state evidence. Charging equipment must match battery chemistry.']
 ],example:['假设质量1.6kg，g=9.81m/s²，重量15.70N，对称四电机理想悬停每个约3.92N。若候选实测每个最大6N，总24N，静态推重比约1.53；这不是自动合格门槛。','At assumed 1.6 kg and g=9.81, weight is 15.70 N and ideal equal hover thrust 3.92 N per motor. Four measured 6 N maxima give static thrust/weight about 1.53, not automatic acceptance.'],error:['推重比、油门开度和续航不能互相直接替换；缺少准确组合测试就保留未知。','Thrust ratio, throttle and endurance are not interchangeable; retain unknowns without matching test data.'],answer:['约3.92N每电机仅是理想均分悬停值，不含控制和环境余量。','About 3.92 N per motor is only ideal equal hover, without control/environment margins.'],task:[['为假设1.6kg平台做可追踪选型表。','Create a traceable selection budget for a hypothetical 1.6 kg vehicle.'],['每个电机的理想悬停推力是多少？','What is ideal equal hover thrust per motor?'],['手算重量与推力，列电机/桨/电压测试表所需字段，不指定未经核对商品。','Calculate weight/thrust and list required motor/prop/voltage test fields without unverified product choices.'],['指出静态估算没有包含什么。','Identify omitted dynamics and conditions.'],['增加200g载荷重新计算，并标出受影响部件。','Add 200 g payload and recalculate affected requirements.'],['提交质量表、公式、候选数据来源和未知项。','Submit mass budget, formulas, candidate sources and unknowns.'],['量纲正确，未把油门当推力比例，所有候选结论可追踪。','Use correct units, distinguish throttle/thrust and trace candidate conclusions.']]});

addLesson8({id:'drone-wiring',area:'无人机台架',title:['无人机接线：供电、信号与固定','Drone wiring: power, signals and mounting'],pre:['drone-sizing','hardware-check'],lab:'drone',level:'Intermediate',goal:['能按准确设备引脚表规划无桨接线与断电检查。','Plan propeller-free wiring and unpowered checks from exact pinouts.'],refs:['px4'],sections:[
 ['先按准确版本查引脚','Use exact hardware pinouts','飞控不同版本的POWER、TELEM、GPS、RC和电机输出不一定同序。相同外形插头也可能不同引脚。先写端口、针脚号、功能、电压与方向，再做线缆，两端都标注而不是只记颜色。','POWER, TELEM, GPS, RC and motor outputs differ by controller revision. Identical connector shells can have different pinouts. Document port/pin/function/voltage/direction and label both ends before making cables.'],
 ['电池主线与飞控电源分开确认','Check propulsion and controller supplies','电池主电流经分电系统到ESC；飞控通常通过匹配电源模块获得受控电压及测量。USB可使飞控亮起却不一定给ESC供电。不能因USB能连接就认定整机供电已验证。','Battery propulsion current flows to ESCs through distribution; a matched module commonly powers/monitors the controller. USB may light the controller without powering ESCs. USB connection does not validate the entire power system.'],
 ['固定和走线影响测量','Mounting affects measurement','飞控安装与振动隔离按设备要求，线束留应力释放。磁力计和高电流线相对位置会影响磁测量；电源与信号走线避免不必要的大回路。改变布线后仍应重新检查传感器状态。','Follow controller mounting/isolation guidance and relieve cable strain. High-current wiring can disturb magnetometers. Avoid unnecessary loop area and recheck sensor behavior after routing changes.'],
 ['接电池前完成检查','Check before battery connection','拆除所有桨，检查极性、焊接、绝缘、端子固定和意外短接。首次电源测试使用与系统兼容的限流方案并按厂家程序；过低供电或错误限流器可能使电机测试异常，需要区分设备故障与测试条件。','Remove all props and inspect polarity, joints, insulation, retention and shorts. Use a compatible current-limited first-power method following manufacturer guidance; inadequate test power can itself cause abnormal behavior.']
 ],example:['USB连接时飞控能显示姿态，但ESC无主供电，电机不转并不能单独证明输出配置错误。应先按供电树确认所测环节已具备必要条件。','A USB-powered controller can show attitude while unpowered ESCs cannot run motors. That alone does not prove output configuration is wrong; verify the power tree and test prerequisites.'],error:['不能通过把未知端口逐个试插来找接口；同形连接器不是电气兼容证据。','Do not discover interfaces by trying unknown plugs; matching shape does not prove compatibility.'],answer:['不能；USB和动力电源可能是不同路径，需要分别验证。','No; USB and propulsion power can be separate paths and need separate verification.'],task:[['为无桨平台形成逐针脚接线文件。','Produce pin-by-pin wiring documentation for a propeller-free rig.'],['飞控USB亮灯能证明ESC已供电吗？','Does controller USB power prove ESC power?'],['选一个官方示例板型资料，绘供电树和端口对照，保持实体未上桨。','Use one official example board’s documentation to draw power/port maps with no props fitted.'],['说明主电源、受控飞控电源和信号的区别。','Explain propulsion power, regulated controller power and signals.'],['模拟一个反接或未接参考地错误，在图上定位。','Locate a hypothetical polarity/reference error in the diagram.'],['提交接线表、来源版本和断电检查结果/计划。','Submit pin map, document revision and unpowered results/plan.'],['每针可追踪，供电路径分清，实际执行与计划明确分开。','Trace every pin, distinguish power paths and separate performed checks from plans.']]});

addLesson8({id:'drone-config',area:'无人机台架',title:['飞控配置：机型、方向与传感器校准','Flight-controller setup: frame, orientation and calibration'],pre:['drone-wiring','sensors'],lab:'drone',level:'Intermediate',goal:['能按固件版本核对机型和坐标，解释校准解决与不能解决的问题。','Verify frame/orientation by firmware version and explain calibration limits.'],refs:['px4'],sections:[
 ['固件和机型要匹配','Match firmware and airframe','记录飞控硬件、固件版本、地面站版本和机型配置。相同“四旋翼”也可能有不同电机布局、输出顺序与机架几何。先选正确空气动力构型，再核对每个输出功能，不复制其他机型参数。','Record hardware, firmware, ground-station version and airframe configuration. Quadrotors can differ in layout/output order. Select the correct geometry and verify assignments instead of copying another airframe’s parameters.'],
 ['姿态显示与实际动作对应','Match displayed and actual attitude','无桨、未解锁时轻轻改变机体姿态，检查地面站模型方向是否一致：抬机头应对应预期俯仰变化。若不一致，先查安装方向、轴定义与配置，而不是调整PID掩盖坐标错误。','With props removed and disarmed, gently change body attitude and compare display direction. Mismatch calls for checking mounting/frame configuration, not tuning PID around a coordinate error.'],
 ['校准需要合适条件','Calibrate under suitable conditions','按准确固件指引完成加速度计、陀螺、罗盘等需要的校准，保持规定静止或姿态序列，远离干扰源。校准估计偏置或尺度等参数，但不能修复松动安装、损坏传感器和持续磁干扰。','Follow version-specific accelerometer/gyro/compass procedures with required stillness/poses and suitable surroundings. Calibration estimates parameters; it cannot repair loose mounting, damage or continuing interference.'],
 ['保留基线和检查告警','Preserve a baseline','保存校准结果、关键参数和初始日志，记录每次修改原因。校准显示完成后仍检查姿态、健康状态和静止读数。不要为了通过预检查关闭不了解的安全检查，先解决告警根因。','Save calibration, parameters and baseline logs with change reasons. After completion, inspect attitude, health and stationary readings. Resolve preflight warnings rather than disabling checks you do not understand.']
 ],example:['飞控在机架上旋转90°安装，需要设置与真实安装一致的旋转并验证。仅重新做零偏校准不会自动让错误的机体前向定义正确。','A controller mounted at 90° needs matching orientation configuration and verification. Repeating bias calibration does not automatically correct an incorrect body-forward definition.'],error:['校准完成、无告警和允许解锁是不同层次，均不自动证明飞行安全。','Calibration completion, no warnings and arming permission are distinct and do not automatically establish safe flight.'],answer:['先修正/确认安装方向和坐标，再按规定校准与验证；不能靠PID补错轴。','Verify mounting/frame configuration, then calibrate and validate; PID cannot repair a wrong axis definition.'],task:[['在教学模型完成飞控朝向和校准流程审核。','Audit orientation/calibration flow in the teaching model.'],['旋转安装导致轴不对应，增大PID能解决吗？','Can increasing PID fix mismatched axes from rotated mounting?'],['确认前向与机型，列出校准前提，再按模型通过方向确认。','Verify forward/frame, list calibration prerequisites and complete modeled orientation confirmation.'],['解释偏置校准与坐标旋转的区别。','Explain bias calibration versus frame rotation.'],['在纸面把飞控反向安装，写出需要更新的设置和验证。','Consider reversed mounting and specify updated settings/checks.'],['提交版本卡、方向图和校准证据类别。','Submit versions, frame diagram and calibration evidence category.'],['实际姿态与显示方向一致的检查有记录，未跳过未知告警。','Document direction agreement and do not bypass unexplained warnings.']]});

addLesson8({id:'drone-noprop',area:'无人机台架',title:['无桨电机测试：编号、方向与停止','Propeller-free motor tests: identity, direction and stop'],pre:['drone-config','rc-link'],lab:'drone',level:'Intermediate',goal:['能按具体机型验证电机身份与方向，并保留停止控制。','Verify motor identity/direction for the actual frame with stop control retained.'],refs:['px4','safety'],sections:[
 ['先建立拆桨状态','Establish propeller removal','所有桨必须实际拆下，不能把低油门当替代。固定机架、清理松动物品，确认停止途径和供电断开方法。网页“拆桨确认”只是流程练习，不证明旁边真实设备已拆桨。','Physically remove every propeller; low throttle is no substitute. Secure the frame, clear loose items and identify stop/power isolation. A webpage checkbox cannot prove real hardware has no props.'],
 ['编号由当前机型定义','Identity comes from the selected frame','逐个调用官方电机测试功能，核对软件编号对应哪个实体位置。编号顺序与旋转方向不跨机型通用。只动一台并观察，记录实际映射；不要让多台同时转掩盖接错。','Use the official individual motor test and match each software identity to a physical position. Ordering/direction are airframe-specific. Test one at a time and record mapping rather than hiding mistakes with simultaneous motion.'],
 ['协议决定是否需要ESC校准','ESC calibration depends on protocol','部分PWM/OneShot ESC可能需要按文档校准端点；DShot或某些CAN ESC不使用同类模拟脉宽端点校准。先查固件与ESC协议，不照搬“所有电调都先拉满油门”的通用教程。','Some PWM/OneShot ESCs need documented endpoint calibration; DShot and some CAN ESCs do not use that analog pulse endpoint procedure. Match firmware/ESC protocol rather than assuming one universal calibration.'],
 ['测试短且可停止','Keep tests bounded and stoppable','教学台每次只让一个电机运行1秒，并可停止。实体测试时间和输出按厂家指引，保持能立即停止和隔离供电。无桨方向通过只验证连接/流程，无法验证装桨推力、振动和飞控稳定性。','The teaching rig runs one motor for one second with stop control. Real output/duration follow manufacturer guidance and retain immediate stop/isolation. A propeller-free direction check does not validate thrust, vibration or flight stability.']
 ],example:['软件测试电机1，实际电机3位置响应，说明映射不符合当前机型。停止、断电后核对输出分配与线缆；不能靠交换桨方向来“抵消”编号错误。','If software motor 1 activates physical position 3, mapping disagrees with the selected frame. Stop and inspect allocation/wiring; propeller changes cannot compensate for an identity mismatch.'],error:['看见电机转动不等于编号、方向、协议和停止路径都正确。','Rotation alone does not verify identity, direction, protocol and stopping.'],answer:['先停止并核对输出映射，保留拆桨状态，不能继续同时测试掩盖错误。','Stop and verify allocation while retaining propeller removal; do not hide errors with simultaneous tests.'],task:[['完成四个电机的一对一无桨检查表。','Complete a one-to-one propeller-free motor check.'],['测试1却看到位置3响应，下一步是什么？','What follows if test 1 activates position 3?'],['在模型确认拆桨、逐台1秒测试，记录身份与停止效果。','Confirm modeled prop removal, test each motor for one second and record identity/stop.'],['说明每个电机编号所依据的机型图。','Identify the airframe diagram defining each motor identity.'],['注入一个映射错误，按停止→核对→修复→重测恢复。','Inject a mapping error and stop, inspect, repair and retest.'],['提交四行映射表及停止检查记录，标明模型。','Submit four mapping rows and stop checks labeled modeled.'],['一对一映射正确、拆桨锁定有效、停止可用，未宣称飞行验证。','Verify one-to-one mapping, prop-removal lock and stop without claiming flight validation.']]});

addLesson8({id:'drone-failsafe',area:'无人机台架',title:['失联、低电与恢复：先在仿真验证','Link loss, low power and recovery: simulation first'],pre:['drone-noprop','c-state'],lab:'drone',level:'Intermediate',goal:['能把故障、检测条件、动作和恢复写成可测试状态表。','Specify faults, detection, actions and recovery as a testable state table.'],refs:['safety'],sections:[
 ['不同故障不是同一个开关','Failures differ','遥控失联、地面站失联、定位丢失、低电压和传感器故障有不同检测条件和可用恢复动作。定义依赖当前模式、位置估计、环境与机型，不能简单全部写“断电”。','RC loss, data-link loss, position loss, low battery and sensor faults differ in detection and available responses. Actions depend on mode/state/environment; “cut power for all faults” is not a universal policy.'],
 ['故障检测需要时间和阈值','Detection uses timing and thresholds','一次丢包不等于持续失联，检测常使用超时或状态组合。写清起始事件、超时、触发动作及优先级。阈值依真实系统规格与日志选定，课堂示例不替代飞控实际安全配置。','A single lost packet is not persistent link loss. Define event, timeout, action and priority. Real thresholds require specifications/logs; classroom numbers do not replace flight-controller safety configuration.'],
 ['先SITL，再无桨检查相关链路','Use simulation before hardware','先在匹配版本SITL中验证故障状态变化，记录模式、告警和命令。无桨台架可检查链路检测、输出停止等适用部分，但不能复现空中返航与着陆。不要在空中首次制造未知失控。','Use version-matched SITL to inspect faults/modes/commands. A propeller-free rig can check applicable link/output behavior but cannot reproduce airborne return or landing. Do not first discover unknown failsafe behavior in flight.'],
 ['恢复也是设计的一部分','Recovery is part of the design','信号回来后是否自动恢复、需要人工确认还是保持保护状态，都要写清并测试。检查最坏情况与重复触发，保留事件时间轴。通过网页版停止不等于真实飞机所有失控保护已经可用。','Specify automatic/manual recovery or latched protection and test it. Preserve event timelines and repeated-trigger behavior. A webpage stop test does not validate all real aircraft failsafes.']
 ],example:['教学台规则可定义“命令超过100ms未更新→停止模型电机，恢复后仍需重新确认”。这是地面流程练习；真实飞行中的返航/着陆/终止动作必须按准确系统和场景配置。','A teaching bench can define stale commands over 100 ms→stop modeled motors, requiring reconfirmation after recovery. This is a ground workflow; real flight return/landing/termination depends on the actual system and scenario.'],error:['返航要求位置与返航路径条件，不能把返航按钮当所有故障的可靠答案。','Return requires suitable position/path conditions and is not a universal reliable response.'],answer:['先明确当前状态、可用导航与故障类型，再选择文档支持的动作；课堂停电机不能照搬到空中。','Choose supported actions from state/navigation/fault context; bench motor stopping cannot be copied indiscriminately into flight.'],task:[['建立三种故障与恢复的验收表。','Create acceptance cases for three faults and recoveries.'],['所有故障都直接停电机是否合理？','Is immediate motor stopping reasonable for every fault?'],['分别列失联、低电、定位丢失检测与响应；在模型测试其支持的停止/失联流程。','Specify link/power/position failures and test only model-supported stop/link flows.'],['说明哪些只能由SITL或真实系统另行验证。','Identify checks requiring SITL or actual system validation.'],['增加恢复后不自动启动的条件，重复触发测试。','Add nonautomatic restart conditions and repeat fault cycles.'],['提交状态表、时间轴和未验证边界。','Submit state table, timeline and unverified boundaries.'],['检测/动作/恢复均明确，模型结果没有被扩大成实飞资格。','Define detection/action/recovery without treating modeled results as flight qualification.']]});

addLesson8({id:'ros2-setup',area:'ROS 2与机器人',title:['ROS 2环境：发行版、终端与首个节点','ROS 2 environment: distribution, shell and first node'],pre:['linux-process','python','mcu'],lab:'ros',level:'Intermediate',goal:['能确认ROS 2运行环境并启动、查询、停止一个示例节点。','Verify a ROS 2 environment and start, inspect and stop an example node.'],refs:['ros'],sections:[
 ['ROS 2不是一套独立操作系统','ROS 2 runs on a host OS','ROS 2提供通信、工具和库，仍依赖宿主系统、编译器和包。课程以ROS 2为方向，不混用ROS 1命令。选择发行版前核对它支持的系统、架构、仿真器与目标机器人SDK版本。','ROS 2 provides communication/tools/libraries atop a host OS and dependencies. This route uses ROS 2 rather than mixing ROS 1 commands. Match distribution, OS, architecture, simulator and robot SDK.'],
 ['安装记录比记一句命令重要','Record the environment contract','可选择官方支持组合，例如Jazzy对应的Ubuntu安装路线，但要以当前官方支持表确认。WSL、虚拟机与原生系统对图形、USB和网络的条件不同。网页不附带真实ROS运行环境，安装按官方步骤单独完成。','Choose an officially supported combination, such as the Jazzy Ubuntu installation route, verified against its support table. WSL/VM/native graphics, USB and network differ. This webpage does not bundle a running ROS installation.'],
 ['每个终端需要正确环境','Configure each shell','在bash中source已安装发行版的setup.bash，使该终端能找到ROS包。路径必须是实际安装路径，不照抄不存在的目录。新终端不一定继承你之前手动source的环境；echo $ROS_DISTRO可帮助核对发行版。','In bash, source the installed distribution’s setup.bash so the shell finds ROS packages. Use the actual path. A new terminal may not inherit prior manual setup; echo $ROS_DISTRO helps identify the distribution.'],
 ['一个示例拆成可验证动作','Verify one example stepwise','在准备好turtlesim的环境中运行ros2 run turtlesim turtlesim_node，再在另一个已配置终端用ros2 node list查看。关闭示例后再次查询，理解节点是运行实体，不是硬盘上的包目录。','With turtlesim installed, run ros2 run turtlesim turtlesim_node and query ros2 node list from another configured terminal. Query after stopping to distinguish a running node from an installed package directory.']
 ],example:['两个终端都配置环境：A运行turtlesim节点，B查询节点列表。A用Ctrl+C结束后，该节点应不再作为正常运行节点出现；发现缓存或延迟时复查进程与环境。','Configure both shells: A runs turtlesim, B lists nodes. After Ctrl+C in A, it should no longer appear as an active node; investigate discovery delay/cache using process and environment checks.'],error:['ros2命令可用不代表所有包已装，节点列表为空也不一定表示安装坏了。','An available ros2 command does not mean every package is installed; an empty graph need not mean broken installation.'],answer:['包是安装的代码与资源，节点是运行中的功能实体；包存在不自动启动节点。','A package contains installed code/resources; a node is a running functional entity. Packages do not auto-start nodes by existing.'],task:[['建立可复现ROS 2示例环境卡。','Create a reproducible ROS 2 example environment record.'],['安装turtlesim包后一定已经有节点在运行吗？','Does installing turtlesim guarantee a running node?'],['核对发行版和Shell环境，启动示例、列节点、停止并复查；未安装时明确记录为准备阶段。','Verify distro/shell, start/list/stop/recheck; explicitly label preparation-only if not installed.'],['解释包、可执行文件、进程和节点。','Explain package, executable, process and node.'],['新终端从说明开始重复，不依赖旧终端。','Repeat from instructions in a fresh terminal.'],['提交版本、安装来源、启动与停止证据。','Submit version/source and start/stop evidence.'],['能独立重建示例运行，安装计划不冒充实际ROS验证。','Reproduce the example and distinguish planned from actual ROS verification.']]});

addLesson8({id:'ros2-topics',area:'ROS 2与机器人',title:['节点、话题、消息类型与观测','Nodes, topics, message types and observation'],pre:['ros2-setup','protocol'],lab:'ros',level:'Intermediate',goal:['能查出谁发布什么类型给谁，并观察消息而不误发真实机器人指令。','Identify publishers/types/subscribers and observe messages without commanding real hardware.'],refs:['ros'],sections:[
 ['话题是有类型的数据通道','Topics carry typed data','节点可发布多个话题，也可订阅多个话题。话题名字类似通信地址，消息类型决定字段结构；名字相同但类型不匹配不能当作同一有效接口。还需核对QoS与发现环境。','A node can publish/subscribe to multiple topics. The name identifies a channel and the type specifies fields. Matching names alone do not establish compatibility; type, QoS and discovery matter.'],
 ['先只读观察现有系统','Observe before publishing','ros2 topic list -t列话题与类型；ros2 topic info查看端点信息；ros2 interface show查看类型字段。先画通信图再决定要发什么，尤其不要把教程cmd_vel直接发到已连接的真实机器人。','Use ros2 topic list -t, topic info and interface show to inspect names, endpoints and fields. Map the graph before publishing, especially before reusing tutorial velocity commands on a connected robot.'],
 ['消息出现与数据新鲜不同','Presence differs from freshness','topic echo显示收到的消息，hz估计观察到的频率，但网络、QoS和订阅者开销影响观测。系统还需时间戳、年龄和有效状态；仅看话题存在不能证明最新数据足够快。','topic echo shows received messages and hz estimates observed rate, affected by network/QoS/overhead. Timestamps, age and validity remain necessary; an existing topic does not prove timely current data.'],
 ['用海龟隔离运动练习','Practice in turtlesim','在独立仿真环境运行键盘遥控海龟，观察/turtle1/cmd_vel和/turtle1/pose。前者是速度命令，后者是状态；不要把命令数值当作已经测得的实际运动。停止发布后行为也要按接收端实现核对。','In an isolated turtlesim setup, observe /turtle1/cmd_vel and /turtle1/pose during keyboard control. Command and measured state are distinct. Verify receiver behavior when publishing stops rather than assuming a universal timeout.']
 ],example:['geometry_msgs/msg/Twist包含linear和angular向量。海龟示例中查看linear.x与angular.z能解释平移和转向命令，但真实底盘还需确认坐标、单位和支持的分量。','Twist contains linear/angular vectors. In turtlesim, inspecting linear.x and angular.z helps explain translation/turn commands. A real base still needs frame, unit and supported-component verification.'],error:['话题名叫cmd_vel并不能自动说明安全范围、坐标系和超时策略。','The name cmd_vel does not define safe limits, frame or timeout policy.'],answer:['必须同时核对名字、消息类型、QoS、坐标单位和数据时效，不止看到话题。','Check name, type, QoS, frames/units and freshness rather than mere topic existence.'],task:[['画海龟遥控的发布订阅关系。','Map turtlesim teleoperation publishers/subscribers.'],['话题存在能证明消息持续更新吗？','Does topic existence prove continuing updates?'],['只读列类型、查接口、echo命令与状态，在独立海龟环境观察键盘动作。','Inspect types/interfaces and echo command/state in isolated turtlesim while observing keyboard motion.'],['区分命令、状态和观测频率。','Distinguish command, state and observed frequency.'],['停止发布端，记录接收端行为和消息年龄。','Stop the publisher and record receiver behavior/message age.'],['提交通信图、类型字段和时间记录。','Submit graph, fields and timing record.'],['能从图追到端点，未把命令当测量或向未知真实设备发布。','Trace endpoints without confusing command/measurement or publishing to unknown hardware.']]});

addLesson8({id:'ros2-interfaces',area:'ROS 2与机器人',title:['服务、动作、参数、QoS与记录回放','Services, actions, parameters, QoS and recording'],pre:['ros2-topics','linux-process'],lab:'ros',level:'Intermediate',goal:['能按任务时长和交互方式选择接口，并说明回放边界。','Choose an interface by interaction/duration and explain replay limits.'],refs:['ros'],sections:[
 ['三种交互形式','Three interaction patterns','持续测量适合话题；短请求与响应可用服务；持续目标、反馈和取消常用动作。它们都是软件接口，是否实时、是否允许取消、超时如何处理仍取决于实现，不由名字自动保证。','Topics suit streams, services suit request/response and actions suit longer goals with feedback/cancel. Timing, cancellation and timeout guarantees still depend on implementation.'],
 ['参数是配置不是任意内存','Parameters are configuration','参数可保存阈值、名称或速度限制等配置，类型与允许范围要有规则。运行时能否修改、修改是否立刻生效由节点实现决定。记录启动参数与修改时间，避免不同运行条件被误比较。','Parameters configure values such as thresholds/names/limits with types and bounds. Dynamic modification/effect depends on the node. Preserve startup values and changes for fair comparisons.'],
 ['QoS要满足兼容与需求','QoS needs compatibility and intent','可靠性、历史深度、持久性等策略影响传输和缓存。传感器高频数据与一次配置状态需求不同，选择不是一律越可靠越好。收不到数据时检查端点QoS，不直接归因网络断开。','Reliability, history and durability affect transport/caching. High-rate sensing and persistent configuration differ. More reliability is not universally better; inspect QoS compatibility before blaming networking.'],
 ['回放不会重建全部世界','Replay has limits','rosbag记录选定话题及时间信息，回放适合重复分析。未记录的参数、软件版本、硬件状态和外部环境不会自动恢复；某些系统还需一致的仿真时间。回放到真机命令端可能产生动作，应在隔离环境使用。','rosbag records selected topics/timing for repeatable analysis, not all parameters, versions, hardware or environment. Some consumers need consistent simulated time. Replay commands only in isolated contexts because real recipients could move.']
 ],example:['“连续发布温度”选话题，“查询一次设备信息”可选服务，“移动到目标并可取消”可选动作。三者还需错误码、超时和坐标约定。','Streaming temperature suits a topic; one device-info query can use a service; moving to a cancellable goal suits an action. All still need errors, timeouts and frame contracts.'],error:['录包成功不代表记录了所有复现所需信息，回放也不等于真实物理重复。','A successful bag is not necessarily complete reproduction evidence, and replay is not repeated physics.'],answer:['长时任务需反馈和取消时动作通常更适合，但要验证服务端实际支持。','An action often suits long tasks needing feedback/cancel, subject to server support.'],task:[['为一个虚拟机器人选择三种接口并设计记录计划。','Choose three interfaces and a recording plan for a virtual robot.'],['移动目标需要中途反馈与取消，更适合哪类接口？','Which interface fits movement with feedback/cancel?'],['列话题/服务/动作/参数，核对示例类型与QoS，在隔离环境记录选定状态话题。','List interfaces/parameters, inspect types/QoS and record selected state topics in isolation.'],['说明哪些信息没有进包以及如何补记。','Explain missing reproduction information and how to preserve it.'],['用相同输入回放两次比较处理输出。','Replay identical input twice and compare processing outputs.'],['提交接口选择表、记录清单和版本参数。','Submit interface choices, recording inventory and version/parameters.'],['交互选择合理，回放范围明确且不连接未知实体执行端。','Choose appropriate patterns and bound replay away from unknown hardware actuators.']]});

addLesson8({id:'ros2-workspace',area:'ROS 2与机器人',title:['工作区、包、发布订阅程序与构建','Workspaces, packages, publisher/subscriber programs and builds'],pre:['ros2-interfaces','c-modules','python'],lab:'ros',level:'Intermediate',goal:['能解释src/build/install/log并构建、启动、修改一个最小节点对。','Explain workspace directories and build/run/modify a minimal node pair.'],refs:['ros'],sections:[
 ['工作区目录各有职责','Workspace directory roles','src保存源包；colcon构建产生build、install和log等输出。package.xml描述包信息与依赖，构建文件描述如何生成/安装程序。提交可编辑项目时保留源码与依赖说明，不把本机缓存当唯一交付。','src holds source packages; colcon produces build/install/log outputs. package.xml describes dependencies and build files define generation/install. Preserve source and dependency instructions rather than treating machine-local caches as the deliverable.'],
 ['underlay和overlay影响查找','Underlay and overlay affect lookup','先配置已安装ROS环境，再构建自己的工作区，随后在新终端source工作区安装环境。多个工作区叠加可能遮蔽同名包。查包实际来自哪个安装前缀，避免改了源码却运行另一份。','Configure installed ROS, build the workspace and source its install environment in a fresh terminal. Overlays can shadow same-named packages. Verify the resolved package prefix instead of unknowingly running a different copy.'],
 ['最小发布订阅程序的循环','A minimal node pair','发布节点创建定时器与发布器，定期构造消息；订阅节点注册回调并在执行器spin中处理消息。程序不是写一次publish就自动永远运行；回调内长期阻塞也会影响后续处理。','A publisher timer periodically constructs messages; a subscriber registers callbacks processed by an executor while spinning. One publish call does not create endless execution, and blocking callbacks can delay later work.'],
 ['改一个字段验证新构建','Verify the changed build','按官方当前发行版示例建立Python或C++最小节点对，先原样运行，再只改消息前缀或周期。记录代码差异、构建结果、解析包位置和新输出。测试先在本机无实体执行器环境进行。','Build the official distro-matched minimal Python/C++ pair, run unchanged, then modify only prefix or period. Preserve diff/build status/resolved prefix/new output, isolated from physical actuators.']
 ],example:['把发布前缀由Hello改为Sample，重新构建/安装并加载正确overlay，订阅输出应出现Sample。若还是Hello，先查运行包路径与环境，不能只重复修改源码。','Change publisher prefix Hello to Sample, rebuild/install and use the correct overlay. If subscribers still see Hello, inspect package resolution/environment rather than repeatedly editing source.'],error:['src改动、构建输出和运行环境是三件事，不会总自动同步。','Source changes, build outputs and runtime environment do not always update automatically.'],answer:['可能运行了旧安装或另一个overlay，应核对包前缀、构建成功与source环境。','An old install or another overlay may be running; inspect prefix, build status and sourced environment.'],task:[['建立可交给同伴重建的最小节点对。','Create a minimal node pair a peer can rebuild.'],['改源码后输出没变，一定是订阅者坏了吗？','Does unchanged output after editing prove a broken subscriber?'],['跟随匹配发行版官方节点对，构建运行，再改消息标记。','Build/run the distro-matched official pair and change its marker.'],['画源码→构建→安装→环境→运行链。','Draw source→build→install→environment→execution.'],['在干净工作区按依赖说明重建，或由同伴复现。','Rebuild in a clean workspace or have a peer reproduce it.'],['提交源码、依赖、构建命令、包前缀及新输出。','Submit source, dependencies, build command, prefix and new output.'],['新环境可重建，旧输出问题有定位证据，未把网页动画当ROS运行。','Rebuild cleanly and diagnose stale output without calling webpage animation ROS execution.']]});

addLesson8({id:'ros2-urdf',area:'ROS 2与机器人',title:['URDF、关节状态、TF与可视化','URDF, joint states, TF and visualization'],pre:['ros2-workspace','robot','linux-ros'],lab:'ur5',level:'Advanced',goal:['能解释模型树、关节轴和TF来源，并核对单位与坐标。','Explain model tree, joint axes and TF sources and verify units/frames.'],refs:['urdf','ros'],sections:[
 ['link和joint组成树','Links and joints form a tree','URDF用link描述刚体，用joint连接父子刚体；关节指定类型、原点、轴和必要限制。模型通常是树结构，闭链不能随意加一条普通父子关系。视觉网格、碰撞几何和惯性各有不同用途。','URDF describes rigid links joined in a tree with joint type/origin/axis/limits. Closed loops are not created by arbitrarily adding another ordinary parent edge. Visual, collision and inertial data serve different roles.'],
 ['单位和原点先核对','Check units and origins','ROS常规SI约定使用米、弧度与秒。毫米网格若误当米会大1000倍；90°输入按弧度应约1.571。joint origin表示父子关系中的固定安装变换，axis在规定关节坐标中表达，不是屏幕上的方向。','ROS conventions typically use meters, radians and seconds. Millimeters interpreted as meters scale by 1000; 90° is about 1.571 rad. Joint origin is a fixed mounting transform and axis belongs to the defined joint frame, not the screen.'],
 ['模型不会自己发布动态TF','A model does not publish dynamic TF by itself','robot_state_publisher读取机器人描述与joint_states，计算连杆变换。可动关节需要与模型名称匹配的状态；固定关节按固定关系发布。RViz显示结果，不等于物理引擎，也不会自动求逆运动学。','robot_state_publisher uses a robot description and joint_states to compute link transforms. Moving joints need matching names/states; fixed joints use fixed relationships. RViz displays data, not physics or automatic IK.'],
 ['从一个关节到整机','Validate one joint at a time','先用两连杆确认正方向与原点，再看完整机械臂。打开局部坐标轴，逐关节改变小角度观察哪段移动；错误发生时查parent/child、origin、axis和单位。真实负载能力还需碰撞、动力学和驱动限制。','Verify two links first, then the arm. Show local axes and change one small angle at a time. Inspect parent/child, origin, axis and units on errors. Physical capability additionally needs collision/dynamics/actuator limits.']
 ],example:['一根0.11m连杆绕本地z轴转π/2，二维投影可从x方向转向y方向；0.11m对应110mm。若网格尺寸用110却按米解释，会出现巨大模型。','A 0.11 m link rotated π/2 around local z can move in projection from x toward y. 0.11 m is 110 mm; interpreting 110 mesh units as meters creates a huge model.'],error:['外观漂亮的网格不自动拥有正确碰撞体、惯量、关节轴或真实控制接口。','An attractive mesh does not automatically have correct collision, inertia, axes or control interfaces.'],answer:['URDF描述结构，robot_state_publisher结合关节状态生成变换；RViz只是显示。','URDF describes structure; robot_state_publisher combines joint states to produce transforms; RViz displays them.'],task:[['为一个关节建立模型与坐标核对表。','Create a model/frame check for one joint.'],['只有URDF文件就一定有动态TF在运行吗？','Does a URDF file alone guarantee running dynamic TF?'],['在本地姿态模型逐关节改变角度并显示轴；另按ROS教程验证URDF与joint_states链。','Vary one joint/show axes in the local pose model; separately validate the URDF/joint_states chain using ROS guidance.'],['说明网页姿态计算与真实ROS进程的证据区别。','Distinguish webpage pose calculations from ROS-process evidence.'],['把长度从110mm改为0.11m表达，检查几何等价。','Express 110 mm as 0.11 m and verify geometric equivalence.'],['提交关节表、坐标图和分别标注的模型/ROS证据。','Submit joints/frames and separately labeled model/ROS evidence.'],['单位、方向、父子关系正确，没有把可视化当动力学通过。','Verify units/directions/tree without mistaking visualization for validated dynamics.']]});

addLesson8({id:'ros2-quadruped',area:'ROS 2与机器人',title:['从URDF到机器狗：关节、状态与分级验证','From URDF to a quadruped: joints, state and staged validation'],pre:['ros2-urdf','estimation','foc','rtos'],lab:'go2',level:'Advanced',goal:['能为机器狗建立关节与状态接口清单，按模型→仿真→台架分级验证。','Map quadruped joint/state interfaces and separate model, simulation and hardware validation.'],refs:['ros','urdf'],sections:[
 ['先核对关节清单','Start with the joint inventory','本平台Go2模型有四条腿，每腿3个主动关节，共12个；UR5机械臂另有6个主动关节。它们是两台不同机器人，不能把数量相加当成机器狗配置。固定连接也不计入主动自由度；逐项记录名称、父子链、单位、方向和范围。','This platform has 12 actuated Go2 joints, three per leg, and separately six actuated UR5 joints. These are two different robots and their actuated counts remain separate. Fixed connections do not add actuated degrees of freedom. Inventory names, chains, units, direction and limits.'],
 ['命令、反馈与估计分开','Separate commands, feedback and estimates','关节位置命令、编码器反馈、机身姿态估计和足端接触状态不是同一种信息。消息应带时间与有效性；不要用自己发送的角度当作已经测得的角度。机器狗稳定性还依赖接触与状态估计。','Joint commands, encoder feedback, base estimates and foot contact are different data. Carry timing/validity and never substitute sent angles for measured angles. Stability also depends on contact and estimation.'],
 ['静态姿态不是行走控制','A pose is not locomotion','预设站立、屈腿和关节插值能帮助理解链条，但不会证明重心、摩擦、地面接触和力矩可行。步态规划、全身控制与策略学习需要单独模型和实验；网页不会运行厂商SDK或真实电机控制。','Standing/crouching presets and joint interpolation illustrate chains, not center-of-mass, friction, contact or torque feasibility. Gaits, whole-body control and policies require separate work; the webpage does not run vendor motor control.'],
 ['按层次保留通过证据','Keep evidence for each layer','第一层验证名称、轴和限位；第二层在匹配物理仿真器中检查接触、跌倒与恢复；第三层在合适支撑和监督下低能量核对实机接口。每层都有退出条件，不能用上一层的截图替代下一层。','First verify names/axes/limits; then test contact/falls/recovery in a compatible physics simulator; only later validate hardware interfaces under suitable support/supervision. Evidence from one layer cannot substitute for the next.']
 ],example:['模型某腿膝关节增加0.1rad时向预期方向转动，只说明该模型轴和关节变换一致。若实机编码器正方向相反，还需接口映射与校准，不能把模型角度直接发送。','A modeled knee moving as expected for +0.1 rad confirms that model transform. Opposite hardware encoder sign still needs mapping/calibration; do not send model angles directly without interface verification.'],error:['站立动画、URDF载入、ROS节点在线和实机稳定站立是四种不同验收结果。','A standing animation, loaded URDF, online ROS node and stable physical standing are four different outcomes.'],answer:['不能。关节角外观只验证运动学一部分，接触、动力、延迟与真实接口尚未通过。','No. Joint appearance verifies part of kinematics, not contact, dynamics, latency or hardware interfaces.'],task:[['为机器狗专题整理分级验收档案。','Build a staged quadruped acceptance dossier.'],['网页站立姿态正确能证明实机可以站吗？','Does a correct webpage standing pose prove hardware can stand?'],['逐关节核对名称与局部轴，切换预设姿态并记录范围；制定独立ROS和物理仿真任务。','Inspect joint names/axes and presets/ranges, then specify separate ROS and physics tasks.'],['分别核对Go2的12个主动关节与UR5的6个主动关节，并排除固定连接。','Verify Go2’s 12 and UR5’s six actuated joints separately, excluding fixed connections.'],['选一条腿画命令→反馈→估计→故障停止链路。','Map command→feedback→estimate→fault handling for one leg.'],['提交关节表、分级证据、未验证项与下一阶段计划。','Submit joint inventory, layered evidence, unknowns and next-stage plan.'],['模型检查可重现，真实硬件能力无夸大，每个下一步都有条件。','Reproduce model checks without overstating hardware ability and define prerequisites for every next step.']]});

// These seven lessons use actual local teaching controls, with explicit model limits.
for(const [id,note] of [
 ['breadboard-nodes',['可选择A1–J10孔位，观察A–E/F–J同行五孔连通；P/N轨在5/6之间分断。用A/B探点、跳线、撤销和透视检验教学连通图，真实板仍需断电实测。','Select A1–J10 holes: A–E/F–J five-hole row groups and P/N rails split between 5/6. Probe A/B, add/undo jumpers and use X-ray to inspect the teaching graph. Verify real boards unpowered.']],
 ['perfboard-layout',['模型展示独立焊盘与显式点对点连接，可选点检查并撤销布线；不计算焊点强度、热损伤或真实接触可靠性。','The model shows isolated pads and explicit point-to-point connections with point checks/undo. It does not calculate joint strength, heat damage or contact reliability.']],
 ['drone-architecture',['7个装配模块、飞控朝向、拆桨锁定、单电机1秒测试和停止/失联是流程模型，不计算飞行动力学。','Seven assembly modules, controller orientation, prop-removal lock, one-second individual motor tests and stop/link loss form a workflow model, not flight dynamics.']],
 ['drone-config',['可确认教学飞控前向并检查流程条件；没有真实传感器校准、固件刷写或机体姿态估计。','Confirm modeled controller forward direction and workflow prerequisites; no real sensor calibration, firmware flashing or attitude estimation runs here.']],
 ['drone-noprop',['模型要求拆桨确认后逐个电机运行1秒，可停止并检查失联流程；不向实体ESC发送命令。','The model requires prop-removal confirmation before one-second motor tests with stop/link-loss checks. It sends no commands to physical ESCs.']],
 ['ros2-urdf',['UR5展示6个主动关节、预设姿态与局部坐标轴；只是本地运动学可视化，不运行ROS 2、RViz或接触动力学。','UR5 shows six actuated joints, presets and local axes. This is local kinematic visualization, not ROS 2, RViz or contact dynamics.']],
 ['ros2-quadruped',['Go2展示12个主动关节、预设姿态与局部轴；与UR5的6轴分开计数。没有步态动力学、厂商SDK、ROS 2进程或实机电机控制。','Go2 shows 12 actuated joints, presets and local axes, counted separately from UR5’s six. There is no gait dynamics, vendor SDK, ROS 2 process or hardware motor control.']]
]){LESSON_GUIDE7[id].labMode='simulation';LESSON_GUIDE7[id].labNote=note;}

// Each two-week unit has one new authored lesson plus bounded companion reading,
// then an independent practice/review/project week. Existing 45 lessons remain intact.
const UNITS8=[
 ['pc-parts',[]],['win-files',[]],['win-paths',[]],['win-zip',[]],['win-tools',[]],['win-cmd',[]],
 ['linux-start',[]],['linux-files',[]],['linux-edit',[]],['linux-permissions',[]],['linux-packages',[]],['linux-process',[]],
 ['c-first',['start']],['c-build',['components','c-flow']],['c-values',['kirchhoff']],['c-arithmetic',['wiring-guide']],
 ['c-input',['meter']],['c-conditions',['power']],['c-loops',['rc']],['c-functions',['scope']],
 ['c-arrays',['logic']],['c-strings',['mcu','c-memory']],['c-pointers',['cpu-arch','adc']],['c-structs',['protocol','arduino']],
 ['c-bits',['protection','ac']],['c-modules',['boards','sensors','51']],['c-debug',['motor-control','rtos']],['c-state',['robot','project']],
 ['breadboard-nodes',['solder']],['breadboard-led',['analog-guide']],['breadboard-power',['opamp']],['perfboard-layout',['pcb']],
 ['perfboard-solder',['hotair-guide']],['modules-levels',['stencil-guide']],['modules-power',['reflow-guide']],['hardware-check',['cpp']],
 ['drone-architecture',['rc-link']],['drone-sizing',['vision','python']],['drone-wiring',['esp-net','bus-physical']],
 ['drone-config',['estimation']],['drone-noprop',['foc']],['drone-failsafe',['research']],
 ['ros2-setup',['linux-ros']],['ros2-topics',['vision-ops']],['ros2-interfaces',['ml','bio']],['ros2-workspace',[]],['ros2-urdf',[]],['ros2-quadruped',[]]
];
const CURRICULUM8={
 version:8,weeks:96,hoursPerWeek:[4,6],authoredNewLessons:48,totalLessons:93,
 title:['从电脑零基础到ROS 2机器人：96周学习与实践路线','From computer basics to ROS 2 robotics: a 96-week study and practice route'],
 scope:['共48节新详课，结合原45课；96周包含讲解、独立作业、复习和项目，并不是96篇新详课。每周4–6小时，总计划约384–576小时；未通过可延长，不要求赶进度。','48 new authored lessons combine with the original 45. The 96 weeks include study, independent work, review and projects, not 96 new lesson chapters. At 4–6 hours/week the plan totals about 384–576 hours; extend when gates are not passed.'],
 weeklyRhythm:[
  {hours:[1,1.5],label:['阅读与手算：先预测再看答案','Read and calculate: predict before revealing answers']},
  {hours:[2,3],label:['独立操作：电脑、模型或条件具备的实物练习','Independent work: computer, model or appropriately equipped hardware']},
  {hours:[.5,.75],label:['复盘与延迟回忆：不用原答案重做关键一步','Review and delayed recall: redo a key step without the answer']},
  {hours:[.5,.75],label:['证据与整理：保存输入、过程、结果和边界','Evidence: retain inputs, procedure, results and limitations']}
 ],
 stages:[
  {id:'computer',weeks:[1,12],title:['电脑与文件习惯','Computer and file habits'],goal:['能独立保存、定位、压缩和分享练习项目。','Save, locate, archive and share a practice project independently.'],exitCriteria:['从新解压目录按自己的README打开项目；能说明路径、扩展名、版本和CMD查询结果。','Open a clean extraction using your README and explain paths, extensions, versions and CMD inspection.']},
  {id:'linux',weeks:[13,24],title:['Linux与可复现环境','Linux and reproducible environments'],goal:['能在自己目录管理文本、权限、工具和日志。','Manage text, permissions, tools and logs in your own workspace.'],exitCriteria:['新终端可复现目录、工具版本与一次失败/修复；没有靠不明sudo或扩大权限掩盖错误。','Reproduce location/tool version and a failure/repair in a fresh shell without unexplained privilege changes.']},
  {id:'programming',weeks:[25,56],title:['C编程与电控原理','C programming and electrical foundations'],goal:['完成数值、流程、数组、指针、构建与调试，连接电学及MCU基础。','Learn numeric/control flow, arrays, pointers, builds and debugging alongside electrical/MCU foundations.'],exitCriteria:['独立重建带输入校验和状态机的小程序，解释数组边界、单位、错误路径与测试；能手算LED、RC和基本功率。','Rebuild a validated state-machine program, explain bounds/units/error tests and calculate LED, RC and basic power results.']},
  {id:'hardware',weeks:[57,72],title:['连接、模块与制作','Connections, modules and making'],goal:['把原理图节点变成面包板和洞洞板连接并验收。','Translate schematic nodes to breadboard/perfboard and verify them.'],exitCriteria:['提交连通/隔离地图、双面布局、接口与电源表；模拟与真实检查分开，首次上电流程有依据。','Submit connectivity/isolation, both board views, interfaces and power budget with modeled/physical evidence separated.']},
  {id:'drone',weeks:[73,84],title:['无人机无桨系统验证','Propeller-free drone system validation'],goal:['完成选型推算、接口、方向和停止/失联流程，不以课堂通过代替实飞验证。','Evaluate parts/interfaces/orientation and stop/link-loss flow without substituting classroom results for flight checks.'],exitCriteria:['部件/供电/编号/方向可追踪，逐台无桨检查与故障恢复有记录，明确未验证气动和实飞条件。','Trace parts/power/identity/direction, record individual no-prop checks/recovery and identify unverified flight conditions.']},
  {id:'ros2',weeks:[85,96],title:['ROS 2、模型与机器狗专题','ROS 2, models and quadruped specialization'],goal:['建立真实ROS节点证据，核对URDF与状态链，再规划物理仿真与实机阶段。','Establish ROS-node evidence, validate URDF/state chains and plan physics/hardware stages.'],exitCriteria:['同伴可重建节点示例与记录回放；分别核对Go2 12轴和UR5 6轴，区分网页、ROS、物理仿真和实机四级证据。','A peer can rebuild nodes/replay; verify Go2 12 and UR5 six axes separately and distinguish webpage, ROS, physics and hardware evidence.']}
 ],
 schedule:[],lessonOrder:[],reviewPolicy:['每课第1、7、30天各做一次不看答案的回忆；一周漏学从最后通过的任务继续。每8周的偶数周增加跨课复盘，不用赶进度替代验收。','Recall each lesson without answers after 1, 7 and 30 days. Resume from the last passed task after a missed week. Every eighth week adds cross-lesson review rather than replacing acceptance with schedule pressure.']
};
const lessonMap8=new Map(LESSONS.map(l=>[l.id,l]));
for(let i=0;i<UNITS8.length;i++){
 const [id,companions]=UNITS8[i],lesson=lessonMap8.get(id),task=CASE_TASKS8[id],week=i*2+1;
 const stage=CURRICULUM8.stages.find(s=>week>=s.weeks[0]&&week<=s.weeks[1]);
 const title=[lesson.title,EN_LESSONS[id].title];
 const reviewIds=[i-1,i-4].filter(j=>j>=0).map(j=>UNITS8[j][0]);
 CURRICULUM8.schedule.push({week,stage:stage.id,kind:'lesson',lessonIds:[id,...companions],primaryLessonId:id,reviewLessonIds:reviewIds,hours:[4,6],title,
  task:[task.predict[0]+' 先写预测，再完成本课操作与关联基础阅读。',task.predict[1]+' Write the prediction, then complete the lesson operation and companion foundations.'],
  pass:[task.rubric[0][0]+' 关联课至少完成例题与概念自检，无法解释的先修项先补。',task.rubric[0][1]+' Complete companion examples/concept checks and repair unexplained prerequisites first.'],
  evidence:task.evidence,authoredLesson:true});
 const kind=i===47?'project':((i+1)%4===0?'review':'practice');
 CURRICULUM8.schedule.push({week:week+1,stage:stage.id,kind,lessonIds:[id,...companions],primaryLessonId:id,reviewLessonIds:reviewIds,hours:[4,6],
  title:[(kind==='project'?'综合交付：':kind==='review'?'独立复盘：':'迁移实践：')+title[0],(kind==='project'?'Capstone handoff: ':kind==='review'?'Independent review: ':'Transfer practice: ')+title[1]],
  task:[task.transfer[0]+' 不照抄原操作；完成后用自己的话解释结果与边界。',task.transfer[1]+' Work without copying the original procedure, then explain the result and limits.'],
  pass:[task.rubric[0][0]+' 提交：'+task.evidence[0][0],task.rubric[0][1]+' Submit: '+task.evidence[0][1]],evidence:task.evidence,authoredLesson:false});
}
// Sort all 93 lessons by prerequisites, using the week plan as the stable preference.
const ordered8=new Set();
function orderLesson8(id,active=new Set()){
 if(ordered8.has(id))return;
 if(active.has(id))throw new Error('Curriculum prerequisite cycle: '+id);
 const lesson=lessonMap8.get(id);if(!lesson)throw new Error('Missing prerequisite: '+id);
 const next=new Set(active);next.add(id);for(const pre of lesson.prereq||[])orderLesson8(pre,next);
 ordered8.add(id);CURRICULUM8.lessonOrder.push(id);
}
for(const week of CURRICULUM8.schedule)for(const id of week.lessonIds)orderLesson8(id);
// Preserve LESSON_ROUTE: the original 12-lesson electrical branch remains available.
